// ====== src/entities/moruCat.js (18068 bytes) ======
import * as THREE from 'three';

/**
 * Expressive Chibi 3D Moru Cat Factory.
 * Builds multi-jointed, articulated blacksmith apprentice cats.
 *
 * Each cat contains:
 * - userData.isMoruCat = true
 * - 30+ child meshes (torso, belly, head, cheeks, ears, inner ears, eyes, pupils,
 *   snout, whiskers, collar, golden bell, blacksmith helmet & crest, 4 swinging legs,
 *   paws, 3-segment wagging tail)
 * - Scaled ~2.0x for prominent visual presence
 * - Active quadruped trotting, hopping, and synchronized forge strike celebration
 */

// Fur color palettes for diverse cute blacksmith cats
const CAT_PALETTES = [
  // 0: Classic Orange Tabby
  { fur: 0xf39c12, belly: 0xfef5e7, innerEar: 0xffb7b2, nose: 0xff6b81, helmet: 0x34495e, eye: 0x1b4332 },
  // 1: Tuxedo Blacksmith Cat
  { fur: 0x222f3e, belly: 0xf8f9fa, innerEar: 0xffccd5, nose: 0xff758f, helmet: 0x576574, eye: 0x00b894 },
  // 2: Calico Master Smith
  { fur: 0xe67e22, belly: 0xffffff, innerEar: 0xffafcc, nose: 0xff4d6d, helmet: 0x2c3e50, eye: 0x0984e3 },
  // 3: Cyber Midnight Apprentice (Cyan Accents)
  { fur: 0x1e272e, belly: 0x485460, innerEar: 0x00f2fe, nose: 0x00cec9, helmet: 0x0984e3, eye: 0x00f2fe },
  // 4: Golden Bronze Smith
  { fur: 0xd4ac0d, belly: 0xfcf3cf, innerEar: 0xf9e79f, nose: 0xe74c3c, helmet: 0x7d6608, eye: 0x27ae60 },
  // 5: Cream Siamese Smith
  { fur: 0xfae5d3, belly: 0xfdfefe, innerEar: 0xedbb99, nose: 0x6e2c00, helmet: 0x512e5f, eye: 0x3498db },
  // 6: Emerald Cyber Stray
  { fur: 0x16a085, belly: 0xa3e4d7, innerEar: 0x76d7c4, nose: 0x117a65, helmet: 0x1f618d, eye: 0xf1c40f }
];

export function createMoruCat(index = 0, customPos = null) {
  const catRoot = new THREE.Group();
  catRoot.name = `moru_cat_${index}`;
  catRoot.userData.isMoruCat = true;

  const pal = CAT_PALETTES[index % CAT_PALETTES.length];

  // Materials
  const furMat = new THREE.MeshStandardMaterial({
    color: pal.fur,
    roughness: 0.7,
    metalness: 0.1
  });

  const bellyMat = new THREE.MeshStandardMaterial({
    color: pal.belly,
    roughness: 0.8,
    metalness: 0.05
  });

  const innerEarMat = new THREE.MeshStandardMaterial({
    color: pal.innerEar,
    roughness: 0.6
  });

  const noseMat = new THREE.MeshStandardMaterial({
    color: pal.nose,
    roughness: 0.4
  });

  const eyeMat = new THREE.MeshStandardMaterial({
    color: pal.eye,
    roughness: 0.1,
    metalness: 0.8
  });

  const catchlightMat = new THREE.MeshBasicMaterial({
    color: 0xffffff
  });

  const collarMat = new THREE.MeshStandardMaterial({
    color: 0xe74c3c,
    roughness: 0.4
  });

  const bellMat = new THREE.MeshStandardMaterial({
    color: 0xf1c40f,
    roughness: 0.25,
    metalness: 0.95
  });

  const helmetMat = new THREE.MeshStandardMaterial({
    color: pal.helmet,
    roughness: 0.35,
    metalness: 0.85
  });

  const hornMat = new THREE.MeshStandardMaterial({
    color: 0xd4ac0d,
    roughness: 0.3,
    metalness: 0.9
  });

  const whiskerMat = new THREE.MeshBasicMaterial({
    color: 0xffffff
  });

  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x050810,
    transparent: true,
    opacity: 0.45
  });

  const allChildMeshes = [];
  function registerMesh(mesh, name) {
    mesh.name = name;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.userData.isCatPart = true;
    allChildMeshes.push(mesh);
    return mesh;
  }

  // ==========================================
  // 1. TORSO & BELLY PATCH
  // ==========================================
  // Rounded chubby torso
  const torsoGeo = new THREE.SphereGeometry(0.75, 18, 14);
  torsoGeo.scale(1.0, 0.9, 1.35);
  const torso = registerMesh(new THREE.Mesh(torsoGeo, furMat), 'torso');
  torso.position.set(0, 0.95, 0);
  catRoot.add(torso);

  // White fluffy belly patch
  const bellyGeo = new THREE.SphereGeometry(0.55, 14, 12);
  bellyGeo.scale(0.85, 0.8, 1.1);
  const belly = registerMesh(new THREE.Mesh(bellyGeo, bellyMat), 'belly_patch');
  belly.position.set(0, 0.80, 0.18);
  catRoot.add(belly);

  // Soft ambient ground shadow disc under cat
  const shadowGeo = new THREE.CircleGeometry(0.85, 16);
  const shadowDisc = registerMesh(new THREE.Mesh(shadowGeo, shadowMat), 'shadow_disc');
  shadowDisc.rotation.x = -Math.PI / 2;
  shadowDisc.position.set(0, 0.03, 0); // world y 0.06 at rest (above roads at 0.04)
  shadowDisc.castShadow = false; // fake contact disc must not block the real shadow map
  catRoot.add(shadowDisc);

  // ==========================================
  // 2. CHIBI HEAD PIVOT & FACIAL FEATURES
  // ==========================================
  const headPivot = new THREE.Group();
  headPivot.name = 'head_pivot';
  headPivot.position.set(0, 1.45, 0.85);

  // Cute oversized chibi head sphere
  const headGeo = new THREE.SphereGeometry(0.8, 20, 16);
  headGeo.scale(1.15, 0.95, 1.0);
  const head = registerMesh(new THREE.Mesh(headGeo, furMat), 'chibi_head');
  headPivot.add(head);

  // Left puffy cheek
  const cheekGeo = new THREE.SphereGeometry(0.38, 14, 12);
  const leftCheek = registerMesh(new THREE.Mesh(cheekGeo, bellyMat), 'puffy_cheek_L');
  leftCheek.position.set(-0.52, -0.22, 0.45);
  headPivot.add(leftCheek);

