  catRoot.scale.set(2.0, 2.0, 2.0);

  // Store metadata
  catRoot.userData.meshCount = allChildMeshes.length;
  catRoot.userData.childMeshes = allChildMeshes;
  catRoot.userData.index = index;

  // Path locomotion setup
  let pathType = index % 3; // 0: plaza inner ring, 1: plaza outer ring, 2: avenue patrol
  let orbitRadius = 14 + (index % 4) * 4.5;
  let orbitSpeed = 0.4 + (index % 5) * 0.12;
  let avenueIdx = index % 4; // 0: South (+Z), 1: North (-Z), 2: East (+X), 3: West (-X)
  let avenueProgress = (index * 0.25) % 1.0;
  let avenueDirection = 1;

  let currentAngle = (index / 7) * Math.PI * 2;
  let jumpTimer = 0;
  let isJumping = false;
  let jumpHeight = 0;

