    color: 0x1b1f2e,
    roughness: 0.85,
    metalness: 0.2
  });

  const sidewalkMat = new THREE.MeshStandardMaterial({
    color: 0x242a3d,
    roughness: 0.75,
    metalness: 0.25
  });

  const roadMat = new THREE.MeshStandardMaterial({
    map: roadTex,
    roughness: 0.6,
    metalness: 0.15
  });

  const buildingDarkMat = new THREE.MeshStandardMaterial({
    color: 0x131622,
    roughness: 0.5,
    metalness: 0.5
  });

  const neonTrimColors = [0x00f2fe, 0xff007f, 0xffd166, 0x00ff88, 0x7000ff];
  const beaconMeshes = [];

  // ==========================================
  // 1. GROUND PLANE & PLAZA PERIMETER
  // ==========================================
  // Large ground plane
  const groundGeo = new THREE.PlaneGeometry(320, 320, 4, 4);
  const groundMesh = new THREE.Mesh(groundGeo, groundMat);
  groundMesh.rotation.x = -Math.PI / 2;
  groundMesh.position.y = -0.05;
  groundMesh.receiveShadow = true;
  cityGroup.add(groundMesh);

  // Outer plaza paved ring
  const plazaRingGeo = new THREE.RingGeometry(22, 34, 32);
  const plazaRingMesh = new THREE.Mesh(plazaRingGeo, sidewalkMat);
  plazaRingMesh.rotation.x = -Math.PI / 2;
  plazaRingMesh.position.y = 0.02;
  plazaRingMesh.receiveShadow = true;
  cityGroup.add(plazaRingMesh);

  // ==========================================
  // 2. PAVED ROADS & CROSSWALKS
  // ==========================================
  const roadWidth = 12;
  const avenueLength = 120;

  // 4 Grand Avenues radiating along +/-X and +/-Z from plaza edge (r=34 to 150)
  const avenueConfigs = [
    { x: 0, z: 92, rotY: 0, length: avenueLength },       // South
    { x: 0, z: -92, rotY: Math.PI, length: avenueLength }, // North
    { x: 92, z: 0, rotY: Math.PI / 2, length: avenueLength }, // East
    { x: -92, z: 0, rotY: -Math.PI / 2, length: avenueLength } // West
  ];

  avenueConfigs.forEach(cfg => {
    // Road asphalt mesh with lane markings
    const roadGeo = new THREE.PlaneGeometry(roadWidth, cfg.length, 1, 16);
    // Adjust UVs so road texture repeats along the length
    const uvAttr = roadGeo.attributes.uv;
    for (let i = 0; i < uvAttr.count; i++) {
      uvAttr.setY(i, uvAttr.getY(i) * 12);
    }
    roadGeo.uvsNeedUpdate = true;

    const roadMesh = new THREE.Mesh(roadGeo, roadMat);
    roadMesh.rotation.x = -Math.PI / 2;
    roadMesh.rotation.z = cfg.rotY;
    roadMesh.position.set(cfg.x, 0.04, cfg.z);
    roadMesh.receiveShadow = true;
    cityGroup.add(roadMesh);

    // Sidewalk borders flanking the avenue
    [-roadWidth / 2 - 1.5, roadWidth / 2 + 1.5].forEach(sideOffset => {
      const swGeo = new THREE.BoxGeometry(3, 0.18, cfg.length);
      const swMesh = new THREE.Mesh(swGeo, sidewalkMat);
      if (cfg.rotY === 0 || cfg.rotY === Math.PI) {
        swMesh.position.set(cfg.x + sideOffset, 0.09, cfg.z);
      } else {
        swMesh.position.set(cfg.x, 0.09, cfg.z + sideOffset);
        swMesh.rotation.y = Math.PI / 2;
      }
      swMesh.receiveShadow = true;
