import * as THREE from 'three';
import { createRuneTexture, createMagmaTexture } from './textures.js';

/**
 * Central Moru Blacksmith Anvil Forge Plaza (MoruForge).
 * Features:
 * - Octagonal tiered stone dais
 * - Glowing rune circle & rotating neon holo-rings
 * - Molten magma hearth with flickering embers
 * - Detailed 3D Anvil (base, waist, horn, heel, heated ingot)
 * - Animated Forge Hammer with automatic and manual strikes
 * - Expanding shockwave rings & 150+ spark/ember particles
 * - 8 surrounding rune braziers with eternal cyber flames
 */
export function createForge(scene, state, onStrikeCallback) {
  const forgeGroup = new THREE.Group();
  forgeGroup.name = 'moru_forge';
  scene.add(forgeGroup);

  // Textures
  const runeTex = createRuneTexture();
  const magmaTex = createMagmaTexture();

  // Materials
  const daisMat = new THREE.MeshStandardMaterial({
    color: 0x222736,
    roughness: 0.8,
    metalness: 0.3
  });

  const daisTrimMat = new THREE.MeshStandardMaterial({
    color: 0x3a4259,
    roughness: 0.5,
    metalness: 0.6
  });

  const anvilSteelMat = new THREE.MeshStandardMaterial({
    color: 0x2b313d,
    roughness: 0.35,
    metalness: 0.85
  });

  const ingotMat = new THREE.MeshStandardMaterial({
    color: 0xff5500,
    emissive: 0xff3300,
    emissiveIntensity: 0.9,
    roughness: 0.3,
    metalness: 0.4
  });

  // ==========================================
  // 1. OCTAGONAL TIERED STONE DAIS
  // ==========================================
  // Tier 1 (Lowest, widest octagonal step)
  const tier1Geo = new THREE.CylinderGeometry(20, 21.5, 0.45, 8);
  const tier1Mesh = new THREE.Mesh(tier1Geo, daisMat);
  tier1Mesh.position.y = 0.225;
  tier1Mesh.receiveShadow = true;
  forgeGroup.add(tier1Mesh);

  // Tier 2 (Middle step)
  const tier2Geo = new THREE.CylinderGeometry(15.5, 16.5, 0.45, 8);
  const tier2Mesh = new THREE.Mesh(tier2Geo, daisMat);
  tier2Mesh.position.y = 0.675;
  tier2Mesh.receiveShadow = true;
  forgeGroup.add(tier2Mesh);

  // Tier 3 (Upper dais platform)
  const tier3Geo = new THREE.CylinderGeometry(11.5, 12.5, 0.45, 8);
  const tier3Mesh = new THREE.Mesh(tier3Geo, daisMat);
  tier3Mesh.position.y = 1.125;
  tier3Mesh.receiveShadow = true;
  forgeGroup.add(tier3Mesh);

  // Octagonal metallic trim bands along step edges
  [
    { r: 20.2, y: 0.45 },
    { r: 15.7, y: 0.90 },
    { r: 11.7, y: 1.35 }
  ].forEach(trim => {
    const trimGeo = new THREE.CylinderGeometry(trim.r, trim.r, 0.08, 8, 1, true);
    const trimMesh = new THREE.Mesh(trimGeo, daisTrimMat);
    trimMesh.position.y = trim.y;
    forgeGroup.add(trimMesh);
  });

  // ==========================================
  // 2. GLOWING RUNE CIRCLE & ROTATING NEON HOLO-RINGS
  // ==========================================
  // Floor rune circle
  const runeGeo = new THREE.PlaneGeometry(21, 21);
  const runeMat = new THREE.MeshBasicMaterial({
    map: runeTex,
    transparent: true,
    opacity: 0.95,
    depthWrite: false,
    blending: THREE.AdditiveBlending
  });
  const runeMesh = new THREE.Mesh(runeGeo, runeMat);
  runeMesh.rotation.x = -Math.PI / 2;
  runeMesh.position.y = 1.36;
  forgeGroup.add(runeMesh);

  // Spinning neon holo-rings floating above the dais
  const holoRing1Geo = new THREE.TorusGeometry(7.2, 0.08, 16, 64);
  const holoRing1Mat = new THREE.MeshBasicMaterial({
    color: 0x00f2fe,
    transparent: true,
    opacity: 0.75,
    blending: THREE.AdditiveBlending
  });
  const holoRing1 = new THREE.Mesh(holoRing1Geo, holoRing1Mat);
  holoRing1.position.y = 3.6;
  holoRing1.rotation.x = Math.PI / 4;
  forgeGroup.add(holoRing1);

  const holoRing2Geo = new THREE.TorusGeometry(8.8, 0.08, 16, 64);
  const holoRing2Mat = new THREE.MeshBasicMaterial({
    color: 0xffd166,
    transparent: true,
    opacity: 0.65,
    blending: THREE.AdditiveBlending
  });
  const holoRing2 = new THREE.Mesh(holoRing2Geo, holoRing2Mat);
  holoRing2.position.y = 4.2;
  holoRing2.rotation.z = Math.PI / 6;
  forgeGroup.add(holoRing2);

  // ==========================================
  // 3. MOLTEN MAGMA HEARTH
  // ==========================================
  const hearthGroup = new THREE.Group();
  hearthGroup.position.set(-6.5, 1.35, 0);

  // Stone basin collar
  const hearthBasinGeo = new THREE.CylinderGeometry(2.4, 2.8, 0.6, 16);
  const hearthBasinMesh = new THREE.Mesh(hearthBasinGeo, daisTrimMat);
  hearthBasinMesh.position.y = 0.3;
  hearthGroup.add(hearthBasinMesh);

  // Molten magma surface
  const magmaGeo = new THREE.CircleGeometry(2.1, 24);
  const magmaMat = new THREE.MeshBasicMaterial({
    map: magmaTex
  });
  const magmaMesh = new THREE.Mesh(magmaGeo, magmaMat);
  magmaMesh.rotation.x = -Math.PI / 2;
  magmaMesh.position.y = 0.61;
  hearthGroup.add(magmaMesh);

  // Forge hearth warm flickering point light
  const hearthLight = new THREE.PointLight(0xff6600, 2.5, 18, 1.2);
  hearthLight.position.set(0, 1.5, 0);
  hearthLight.castShadow = true;
  hearthLight.shadow.bias = -0.002;
  hearthGroup.add(hearthLight);

  forgeGroup.add(hearthGroup);

  // ==========================================
  // 4. 8 SURROUNDING RUNE BRAZIERS WITH ETERNAL FLAMES
  // ==========================================
  const brazierCount = 8;
  const brazierPedestalGeo = new THREE.CylinderGeometry(0.35, 0.5, 2.2, 8);
  const brazierBowlGeo = new THREE.CylinderGeometry(0.7, 0.3, 0.5, 8);
  const flameGeo = new THREE.OctahedronGeometry(0.35, 2);
  const flameMat = new THREE.MeshBasicMaterial({
    color: 0x00f2fe,
    wireframe: true
  });

  for (let i = 0; i < brazierCount; i++) {
    const angle = (i / brazierCount) * Math.PI * 2 + (Math.PI / 8);
    const radius = 17.5;
    const bx = Math.cos(angle) * radius;
    const bz = Math.sin(angle) * radius;

    const brazier = new THREE.Group();
    brazier.position.set(bx, 0.45, bz);

    const ped = new THREE.Mesh(brazierPedestalGeo, daisTrimMat);
    ped.position.y = 1.1;
    brazier.add(ped);

    const bowl = new THREE.Mesh(brazierBowlGeo, daisMat);
    bowl.position.y = 2.45;
    brazier.add(bowl);

    const flame = new THREE.Mesh(flameGeo, flameMat);
    flame.position.y = 2.95;
    brazier.add(flame);

    forgeGroup.add(brazier);
  }

  // ==========================================
  // 5. DETAILED 3D ANVIL (Base, Waist, Horn, Heel, Heated Ingot)
  // ==========================================
  const anvilGroup = new THREE.Group();
  anvilGroup.name = 'central_anvil';
  anvilGroup.position.set(0, 1.35, 0);

  // Heavy anvil wooden / basalt block pedestal
  const blockGeo = new THREE.CylinderGeometry(2.4, 2.7, 1.2, 12);
  const blockMat = new THREE.MeshStandardMaterial({
    color: 0x1f1914,
    roughness: 0.9,
    metalness: 0.1
  });
  const blockMesh = new THREE.Mesh(blockGeo, blockMat);
  blockMesh.position.y = 0.6;
  blockMesh.receiveShadow = true;
  anvilGroup.add(blockMesh);

  // Anvil Cast Iron Base
  const anvilBaseGeo = new THREE.BoxGeometry(3.2, 0.6, 2.0);
  const anvilBase = new THREE.Mesh(anvilBaseGeo, anvilSteelMat);
  anvilBase.position.y = 1.5;
  anvilBase.castShadow = true;
  anvilGroup.add(anvilBase);

  // Flared Waist / Body
  const anvilWaistGeo = new THREE.CylinderGeometry(1.0, 1.5, 0.9, 12);
  const anvilWaist = new THREE.Mesh(anvilWaistGeo, anvilSteelMat);
  anvilWaist.position.y = 2.15;
  anvilWaist.scale.set(1.4, 1.0, 0.9);
  anvilWaist.castShadow = true;
  anvilGroup.add(anvilWaist);

  // Upper Main Steel Face
  const anvilFaceGeo = new THREE.BoxGeometry(2.8, 0.8, 1.6);
  const anvilFace = new THREE.Mesh(anvilFaceGeo, anvilSteelMat);
  anvilFace.position.y = 2.9;
  anvilFace.castShadow = true;
  anvilGroup.add(anvilFace);

  // Conical Round Horn (Extending +X forward)
  const hornGeo = new THREE.ConeGeometry(0.7, 1.8, 16);
  const hornMesh = new THREE.Mesh(hornGeo, anvilSteelMat);
  hornMesh.rotation.z = -Math.PI / 2;
  hornMesh.position.set(2.2, 2.9, 0);
  hornMesh.castShadow = true;
  anvilGroup.add(hornMesh);

  // Rectangular Flat Heel (Extending -X backward)
  const heelGeo = new THREE.BoxGeometry(1.2, 0.6, 1.4);
  const heelMesh = new THREE.Mesh(heelGeo, anvilSteelMat);
  heelMesh.position.set(-1.9, 2.8, 0);
  heelMesh.castShadow = true;
  anvilGroup.add(heelMesh);

  // Glowing Heated Ingot on top of the anvil
  const ingotGeo = new THREE.BoxGeometry(1.2, 0.35, 0.7);
  const ingotMesh = new THREE.Mesh(ingotGeo, ingotMat);
  ingotMesh.position.set(0.1, 3.45, 0);
  anvilGroup.add(ingotMesh);

  // Ingot glowing point light
  const ingotLight = new THREE.PointLight(0xff6600, 2.0, 8, 1.5);
  ingotLight.position.set(0.1, 3.8, 0);
  anvilGroup.add(ingotLight);

  // Impact Flash Point Light (triggers on strike)
  const flashLight = new THREE.PointLight(0xffffaa, 0, 16, 1.0);
  flashLight.position.set(0.1, 3.8, 0);
  anvilGroup.add(flashLight);

  forgeGroup.add(anvilGroup);

  // ==========================================
  // 6. ANIMATED BLACKSMITH POWER HAMMER & GANTRY
  // ==========================================
  const gantryGroup = new THREE.Group();
  gantryGroup.position.set(0, 1.35, 0);

  // Heavy steel support arch / gantry
  const archMat = new THREE.MeshStandardMaterial({
    color: 0x333b4d,
    metalness: 0.85,
    roughness: 0.3
  });
  const uprightGeo = new THREE.CylinderGeometry(0.25, 0.35, 6.0, 12);

  // Two rear upright pillars
  const post1 = new THREE.Mesh(uprightGeo, archMat);
  post1.position.set(-2.5, 3.0, 2.0);
  gantryGroup.add(post1);

  const post2 = new THREE.Mesh(uprightGeo, archMat);
  post2.position.set(-2.5, 3.0, -2.0);
  gantryGroup.add(post2);

  // Top crossbeam
  const crossbeamGeo = new THREE.BoxGeometry(1.2, 0.6, 4.8);
  const crossbeam = new THREE.Mesh(crossbeamGeo, archMat);
  crossbeam.position.set(-2.5, 6.0, 0);
  gantryGroup.add(crossbeam);

  // Hammer Pivot Joint (at top of gantry)
  const hammerPivot = new THREE.Group();
  hammerPivot.position.set(-2.5, 6.0, 0);

  // Hammer Arm extending from pivot to over the anvil
  const armGeo = new THREE.BoxGeometry(3.6, 0.35, 0.45);
  const hammerArm = new THREE.Mesh(armGeo, archMat);
  hammerArm.position.set(1.5, 0, 0);
  hammerPivot.add(hammerArm);

  // Massive Hammer Head at the end of the arm
  const headGeo = new THREE.BoxGeometry(1.1, 1.4, 0.9);
  const hammerHead = new THREE.Mesh(headGeo, anvilSteelMat);
  hammerHead.position.set(3.0, -0.6, 0);
  hammerHead.castShadow = true;
  hammerPivot.add(hammerHead);

  gantryGroup.add(hammerPivot);
  forgeGroup.add(gantryGroup);

  // ==========================================
  // 7. EXPANDING SHOCKWAVE RINGS
  // ==========================================
  const shockwaveCount = 3;
  const shockwaves = [];
  const shockwaveGeo = new THREE.RingGeometry(0.5, 0.9, 32);

  for (let i = 0; i < shockwaveCount; i++) {
    const swMat = new THREE.MeshBasicMaterial({
      color: 0x00f2fe,
      transparent: true,
      opacity: 0,
      side: THREE.DoubleSide,
      depthWrite: false,
      blending: THREE.AdditiveBlending
    });
    const swMesh = new THREE.Mesh(shockwaveGeo, swMat);
    swMesh.rotation.x = -Math.PI / 2;
    swMesh.position.set(0, 1.38, 0);
    forgeGroup.add(swMesh);

    shockwaves.push({
      mesh: swMesh,
      mat: swMat,
      active: false,
      progress: 1.0,
      delay: i * 0.08
    });
  }

  // ==========================================
  // 8. 160+ EMBER & SPARK PARTICLES
  // ==========================================
  const sparkCount = 180;
  const sparkGeo = new THREE.BufferGeometry();
  const sparkPositions = new Float32Array(sparkCount * 3);
  const sparkColors = new Float32Array(sparkCount * 3);
  const sparkData = [];

  // Strike impact point in world coords:
  // anvil at y = 1.35 + 3.45 = 4.80, x = 0.1, z = 0
  const impactY = 4.85;

  for (let i = 0; i < sparkCount; i++) {
    // Initial positions at ingot
    sparkPositions[i * 3 + 0] = 0.1;
    sparkPositions[i * 3 + 1] = impactY;
    sparkPositions[i * 3 + 2] = 0;

    // Golden / fiery neon colors
    const r = 1.0;
    const g = 0.4 + Math.random() * 0.5;
    const b = 0.1;
    sparkColors[i * 3 + 0] = r;
    sparkColors[i * 3 + 1] = g;
    sparkColors[i * 3 + 2] = b;

    sparkData.push({
      vx: 0,
      vy: 0,
      vz: 0,
      life: 0,
      maxLife: 0.8 + Math.random() * 0.9
    });
  }

  sparkGeo.setAttribute('position', new THREE.BufferAttribute(sparkPositions, 3));
  sparkGeo.setAttribute('color', new THREE.BufferAttribute(sparkColors, 3));

  const sparkMat = new THREE.PointsMaterial({
    size: 0.4,
    vertexColors: true,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });

  const sparkPoints = new THREE.Points(sparkGeo, sparkMat);
  forgeGroup.add(sparkPoints);

  // Trigger spark burst
  function burstSparks() {
    for (let i = 0; i < sparkCount; i++) {
      sparkPositions[i * 3 + 0] = 0.1 + (Math.random() - 0.5) * 0.4;
      sparkPositions[i * 3 + 1] = impactY;
      sparkPositions[i * 3 + 2] = (Math.random() - 0.5) * 0.4;

      const angle = Math.random() * Math.PI * 2;
      const speed = 4.0 + Math.random() * 9.0;
      const upward = 3.5 + Math.random() * 7.5;

      sparkData[i].vx = Math.cos(angle) * speed;
      sparkData[i].vy = upward;
      sparkData[i].vz = Math.sin(angle) * speed;
      sparkData[i].life = sparkData[i].maxLife;
    }
    sparkGeo.attributes.position.needsUpdate = true;
  }

  // ==========================================
  // 9. ANIMATION STATE & STRIKE LOGIC
  // ==========================================
  let hammerAngle = 0;
  let strikeProgress = 0;
  let isStriking = false;
  let autoStrikeTimer = 0;
  const autoStrikeInterval = 3.5; // automatic periodic strike every 3.5s

  function triggerStrike() {
    isStriking = true;
    strikeProgress = 0;
    state.forgeStrikes = (state.forgeStrikes || 0) + 1;

    // Trigger cat hops callback
    if (onStrikeCallback) {
      onStrikeCallback();
    }
  }

  function update(delta, time) {
    // 1. Rotate rune circle & holo-rings
    runeMesh.rotation.z = time * 0.25;
    holoRing1.rotation.y = time * 0.6;
    holoRing1.rotation.z = Math.sin(time * 0.8) * 0.3 + (Math.PI / 4);
    holoRing2.rotation.y = -time * 0.5;
    holoRing2.rotation.x = Math.cos(time * 0.7) * 0.3;

    // 2. Flickering hearth light
    hearthLight.intensity = 2.2 + Math.sin(time * 18.0) * 0.6 + Math.cos(time * 29.0) * 0.4;

    // 3. Auto periodic strike timer
    autoStrikeTimer += delta;
    if (autoStrikeTimer >= autoStrikeInterval) {
      autoStrikeTimer = 0;
      triggerStrike();
    }

    // 4. Hammer strike animation
    if (isStriking) {
      strikeProgress += delta * 2.8; // ~0.35s strike motion
      if (strikeProgress < 0.4) {
        // Slam down rapidly
        const p = strikeProgress / 0.4;
        hammerAngle = (p * p) * 0.75;
      } else if (strikeProgress < 0.48) {
        // Strike impact moment!
        hammerAngle = 0.75;
        if (!flashLight.userData.flashed) {
          flashLight.userData.flashed = true;
          flashLight.intensity = 6.0;
          burstSparks();
          // Activate shockwaves
          shockwaves.forEach(sw => {
            sw.active = true;
            sw.progress = -sw.delay;
          });
        }
      } else if (strikeProgress < 1.0) {
        // Recoil back up smoothly
        const p = (strikeProgress - 0.48) / 0.52;
        hammerAngle = 0.75 * (1.0 - p);
      } else {
        // Finished
        hammerAngle = 0;
        isStriking = false;
        flashLight.userData.flashed = false;
      }
    } else {
      // Idle slight mechanical breathing
      hammerAngle = Math.sin(time * 1.5) * 0.04;
    }
    hammerPivot.rotation.z = -hammerAngle;

    // 5. Flash light decay
    if (flashLight.intensity > 0.01) {
      flashLight.intensity *= Math.pow(0.05, delta);
    } else {
      flashLight.intensity = 0;
    }

    // 6. Shockwave rings expansion
    shockwaves.forEach(sw => {
      if (!sw.active) return;
      sw.progress += delta * 1.4;
      if (sw.progress > 0 && sw.progress <= 1.0) {
        const s = 1.0 + sw.progress * 18.0;
        sw.mesh.scale.set(s, s, s);
        sw.mat.opacity = Math.sin((1.0 - sw.progress) * Math.PI * 0.5) * 0.85;
      } else if (sw.progress > 1.0) {
        sw.active = false;
        sw.mat.opacity = 0;
      }
    });

    // 7. Spark particle physics
    let activeSparks = 0;
    const pos = sparkGeo.attributes.position.array;
    for (let i = 0; i < sparkCount; i++) {
      if (sparkData[i].life > 0) {
        activeSparks++;
        sparkData[i].life -= delta;

        // Velocity & gravity
        pos[i * 3 + 0] += sparkData[i].vx * delta;
        pos[i * 3 + 1] += sparkData[i].vy * delta;
        pos[i * 3 + 2] += sparkData[i].vz * delta;

        // Gravity
        sparkData[i].vy -= 9.8 * delta;

        // Bounce on dais floor
        if (pos[i * 3 + 1] < 1.4) {
          pos[i * 3 + 1] = 1.4;
          sparkData[i].vy = -sparkData[i].vy * 0.45;
          sparkData[i].vx *= 0.7;
          sparkData[i].vz *= 0.7;
        }
      }
    }
    if (activeSparks > 0) {
      sparkGeo.attributes.position.needsUpdate = true;
    }
  }

  return {
    group: forgeGroup,
    triggerStrike,
    update
  };
}




