import * as THREE from 'three';

/**
 * Procedural CanvasTexture generators for Moru 3D Neon Forge City.
 */

// Helper to create an offscreen canvas
function makeCanvas(width, height) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

/**
 * Procedural Skyscraper Window Facade Texture.
 * Generates rich, multi-colored illuminated window grids with floor bands and architectural details.
 */
export function createSkyscraperTexture(variant = 0) {
  const w = 512;
  const h = 1024;
  const canvas = makeCanvas(w, h);
  const ctx = canvas.getContext('2d');

  // Base building facade material color (deep metallic navy / gunmetal)
  const baseColors = ['#141724', '#161928', '#1a1f33'];
  ctx.fillStyle = baseColors[variant % baseColors.length];
  ctx.fillRect(0, 0, w, h);

  // Vertical architectural mullions / columns
  const cols = 16;
  const rows = 32;
  const padX = 6;
  const padY = 8;
  const cellW = (w - padX * (cols + 1)) / cols;
  const cellH = (h - padY * (rows + 1)) / rows;

  // Color palettes for illuminated windows depending on variant
  const palettes = [
    // Variant 0: Cyberpunk Neon (Cyan, Warm Amber, Neon Violet, Emerald)
    ['#38e8ff', '#ffd166', '#ff4d8d', '#06d6a0', '#74b9ff', '#f368e0'],
    // Variant 1: Golden Forge Corporate (Warm Amber, Golden Glow, Champagne, Cyan accents)
    ['#ffeaa7', '#fdcb6e', '#fab1a0', '#00cec9', '#ffeaa7', '#e17055'],
    // Variant 2: Midnight High-Tech Matrix (Electric Cyan, Ice Blue, Bright White, Mint)
    ['#00f2fe', '#4facfe', '#43e97b', '#38f9d7', '#ffffff', '#a8ff78']
  ];
  const palette = palettes[variant % palettes.length];

  // Draw structural vertical mullion lines
  ctx.fillStyle = '#0f111c';
  for (let c = 0; c <= cols; c++) {
    const x = c * (cellW + padX) + padX * 0.5;
    ctx.fillRect(x - 2, 0, 4, h);
  }

  // Draw floor plates (horizontal spandrels)
  for (let r = 0; r <= rows; r++) {
    const y = r * (cellH + padY) + padY * 0.5;
    ctx.fillStyle = (r % 4 === 0) ? '#282d46' : '#10121d';
    ctx.fillRect(0, y - 3, w, 6);

    // Occasional horizontal LED accent strip across facade
    if (r % 8 === 0) {
      ctx.fillStyle = palette[r % palette.length];
      ctx.globalAlpha = 0.85;
      ctx.fillRect(0, y - 1, w, 2);
      ctx.globalAlpha = 1.0;
    }
  }

  // Draw windows
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = padX + c * (cellW + padX);
      const y = padY + r * (cellH + padY);

      // Deterministic pseudo-randomness for window lights
      const seed = Math.sin(r * 127.1 + c * 311.7 + variant * 47.9) * 43758.5453;
      const rand = seed - Math.floor(seed);

      // ~65% of windows are illuminated in varying intensities
      if (rand > 0.35) {
        const color = palette[Math.floor(rand * palette.length)];
        ctx.fillStyle = color;
        // Varying window brightness for rich depth
        ctx.globalAlpha = 0.55 + (rand * 0.45);
        ctx.fillRect(x, y, cellW, cellH);

        // Soft window frame / inner reflection
        ctx.strokeStyle = '#ffffff';
        ctx.globalAlpha = 0.3;
        ctx.lineWidth = 1;
        ctx.strokeRect(x + 1, y + 1, cellW - 2, cellH - 2);
      } else {
        // Dark unlit window with subtle dark blue sheen
        ctx.fillStyle = '#080a12';
        ctx.globalAlpha = 0.95;
        ctx.fillRect(x, y, cellW, cellH);
      }
    }
  }
  ctx.globalAlpha = 1.0;

  // Add subtle vertical LED light conduit up one side
  if (variant === 0 || variant === 2) {
    ctx.fillStyle = '#00f2fe';
    ctx.globalAlpha = 0.8;
    ctx.fillRect(w - 6, 0, 4, h);
    ctx.globalAlpha = 1.0;
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

/**
 * Paved Road Texture with crisp lane markings, dashed center line, and crosswalk.
 */
export function createRoadTexture() {
  const w = 512;
  const h = 512;
  const canvas = makeCanvas(w, h);
  const ctx = canvas.getContext('2d');

  // Dark asphalt base with subtle texture
  ctx.fillStyle = '#1c1f2b';
  ctx.fillRect(0, 0, w, h);

  // Subtle asphalt grain noise
