dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 10;
dirLight.shadow.camera.far = 280;
dirLight.shadow.camera.left = -90;
dirLight.shadow.camera.right = 90;
dirLight.shadow.camera.top = 90;
dirLight.shadow.camera.bottom = -90;
dirLight.shadow.bias = -0.0005;
scene.add(dirLight);

// Central Forge Plaza Point Light
const forgeLight = new THREE.PointLight(0xff6600, 4.0, 45, 1.8);
forgeLight.position.set(0, 5.5, 0);
forgeLight.castShadow = true;
scene.add(forgeLight);

// Glowing Anvil Light
const anvilRuneLight = new THREE.PointLight(0x00f0ff, 2.5, 25, 2);
anvilRuneLight.position.set(0, 3.8, 0);
scene.add(anvilRuneLight);

// Starfield particles for night mode
const starGeo = new THREE.BufferGeometry();
const starCount = 1200;
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount * 3; i += 3) {
  const rad = 180 + Math.random() * 80;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(Math.random() * 0.9 + 0.1);
  starPos[i] = rad * Math.sin(phi) * Math.cos(theta);
  starPos[i + 1] = rad * Math.cos(phi);
  starPos[i + 2] = rad * Math.sin(phi) * Math.sin(theta);
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 1.2,
  transparent: true,
  opacity: 0.85
});
const starField = new THREE.Points(starGeo, starMat);
scene.add(starField);

// Atmosphere Theme Switcher
function applyTheme(themeName) {
  state.theme = themeName;
  document.querySelectorAll('.btn-toggle[id^="mode-"]').forEach(btn => btn.classList.remove('active'));
  const activeBtn = document.getElementById(`mode-${themeName}`);
  if (activeBtn) activeBtn.classList.add('active');

  if (themeName === 'night') {
    scene.background.setHex(0x060814);
    scene.fog.color.setHex(0x060814);
    scene.fog.density = 0.0085;
    ambientLight.color.setHex(0x182442);
    ambientLight.intensity = 1.1;
    dirLight.color.setHex(0x3860bb);
    dirLight.intensity = 1.3;
    dirLight.position.set(60, 90, 50);
    forgeLight.color.setHex(0xff5500);
    forgeLight.intensity = 4.2;
    anvilRuneLight.color.setHex(0x00f0ff);
    starField.visible = true;
  } else if (themeName === 'gold') {
    scene.background.setHex(0x281208);
