    ambientLight.color.setHex(0x3d2112);
    ambientLight.intensity = 1.3;
    dirLight.color.setHex(0xffaa44);
    dirLight.intensity = 2.4;
    dirLight.position.set(75, 45, -30); // Low sunset angle
    forgeLight.color.setHex(0xff3700);
    forgeLight.intensity = 5.0;
