}
state.setTheme = applyTheme;

// --- Central Plaza & Ground Layout ---
const cityGroup = new THREE.Group();
scene.add(cityGroup);

// Main Ground Base
const groundGeo = new THREE.PlaneGeometry(300, 300);
const groundMat = new THREE.MeshStandardMaterial({
