});
const plaza = new THREE.Mesh(plazaGeo, plazaMat);
plaza.position.y = 0.175;
plaza.receiveShadow = true;
cityGroup.add(plaza);

// Plaza Neon Inlay Rings
const ringMatCyan = new THREE.MeshBasicMaterial({ color: 0x00f0ff });
const ringMatGold = new THREE.MeshBasicMaterial({ color: 0xffaa00 });

const ring1Geo = new THREE.RingGeometry(22.6, 22.9, 64);
const ring1 = new THREE.Mesh(ring1Geo, ringMatCyan);
ring1.rotation.x = -Math.PI / 2;
ring1.position.y = 0.36;
cityGroup.add(ring1);

const ring2Geo = new THREE.RingGeometry(14.8, 15.1, 64);
const ring2 = new THREE.Mesh(ring2Geo, ringMatGold);
ring2.rotation.x = -Math.PI / 2;
ring2.position.y = 0.36;
cityGroup.add(ring2);

const ring3Geo = new THREE.RingGeometry(7.8, 8.1, 48);
const ring3 = new THREE.Mesh(ring3Geo, ringMatCyan);
ring3.rotation.x = -Math.PI / 2;
ring3.position.y = 0.36;
cityGroup.add(ring3);

// Decorative Radial Spokes in Plaza
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const spokeGeo = new THREE.PlaneGeometry(0.35, 14.5);
  const spoke = new THREE.Mesh(spokeGeo, ringMatCyan);
  spoke.rotation.x = -Math.PI / 2;
  spoke.rotation.z = angle;
  spoke.position.set(Math.cos(angle) * 15.2, 0.36, Math.sin(angle) * 15.2);
  cityGroup.add(spoke);
}

// Inner Ring Road (radius 24 to 34)
const roadMat = new THREE.MeshStandardMaterial({
  color: 0x0f131c,
  roughness: 0.9,
  metalness: 0.15
});
const ringRoadGeo = new THREE.RingGeometry(23.8, 33.5, 64);
const ringRoad = new THREE.Mesh(ringRoadGeo, roadMat);
ringRoad.rotation.x = -Math.PI / 2;
ringRoad.position.y = 0.02;
ringRoad.receiveShadow = true;
cityGroup.add(ringRoad);

// Road Markings (Dashed Yellow Center Line)
const dashMat = new THREE.MeshBasicMaterial({ color: 0xffcc00 });
for (let i = 0; i < 48; i++) {
  const angle = (i / 48) * Math.PI * 2;
  const dashGeo = new THREE.PlaneGeometry(0.35, 1.8);
  const dash = new THREE.Mesh(dashGeo, dashMat);
  dash.rotation.x = -Math.PI / 2;
  dash.rotation.z = angle + Math.PI / 2;
  dash.position.set(Math.cos(angle) * 28.6, 0.03, Math.sin(angle) * 28.6);
  cityGroup.add(dash);
}

// 4 Cardinal Boulevards extending out from Ring Road
const boulevards = [
  { rot: 0, x: 0, z: 62 },           // South
  { rot: Math.PI, x: 0, z: -62 },    // North
  { rot: Math.PI / 2, x: 62, z: 0 }, // East
  { rot: -Math.PI / 2, x: -62, z: 0 }// West
];

boulevards.forEach(b => {
  const bGeo = new THREE.PlaneGeometry(9.6, 58);
  const bMesh = new THREE.Mesh(bGeo, roadMat);
  bMesh.rotation.x = -Math.PI / 2;
  bMesh.rotation.z = b.rot;
  bMesh.position.set(b.x, 0.02, b.z);
  bMesh.receiveShadow = true;
  cityGroup.add(bMesh);

  // Road lines
  for (let d = -26; d <= 26; d += 4) {
    const dGeo = new THREE.PlaneGeometry(0.3, 2.2);
    const dMesh = new THREE.Mesh(dGeo, dashMat);
    dMesh.rotation.x = -Math.PI / 2;
    dMesh.rotation.z = b.rot;
    if (b.rot === 0 || b.rot === Math.PI) {
      dMesh.position.set(b.x, 0.03, b.z + d);
    } else {
      dMesh.position.set(b.x + d, 0.03, b.z);
    }
    cityGroup.add(dMesh);
  }

  // Crosswalk markings at plaza intersection
  for (let c = -4; c <= 4; c += 0.8) {
