}

// --- The Moru Blacksmith Anvil (Moru = Anvil in Korean) ---
const anvilGroup = new THREE.Group();
anvilGroup.position.set(0, 1.15, 0);
forgePlazaGroup.add(anvilGroup);

const steelMat = new THREE.MeshStandardMaterial({
  color: 0x2c3547,
  metalness: 0.88,
  roughness: 0.22
});

const glowingSteelMat = new THREE.MeshStandardMaterial({
  color: 0x3d4b66,
  metalness: 0.9,
  roughness: 0.2,
  emissive: 0xff4400,
  emissiveIntensity: 0.6
});

// Anvil Base (flared rectangular stepped base)
const anvilBaseGeo = new THREE.BoxGeometry(3.6, 0.75, 2.0);
const anvilBase = new THREE.Mesh(anvilBaseGeo, steelMat);
anvilBase.position.y = 0.375;
anvilBase.castShadow = true;
anvilBase.receiveShadow = true;
