    collar.position.set(0, 0.18, -0.42);
    collar.rotation.x = Math.PI / 4;
    this.bodyGroup.add(collar);

    // Mini Anvil Charm hanging from collar
    const miniAnvilGeo = new THREE.BoxGeometry(0.18, 0.1, 0.12);
    const miniAnvil = new THREE.Mesh(miniAnvilGeo, goldMat);
    miniAnvil.position.set(0, 0.05, -0.52);
    this.bodyGroup.add(miniAnvil);

    // Head Group
    this.headGroup = new THREE.Group();
    this.headGroup.position.set(0, 0.35, -0.65);
    this.bodyGroup.add(this.headGroup);

    // Rounded Cute Head
    const headGeo = new THREE.SphereGeometry(0.52, 16, 16);
    const head = new THREE.Mesh(headGeo, coatMat);
    head.scale.set(1.1, 0.98, 1.0);
    head.castShadow = true;
    this.headGroup.add(head);

    // Cat Ears (left and right pointy cones)
    const earGeo = new THREE.ConeGeometry(0.24, 0.42, 4);
    const innerEarGeo = new THREE.ConeGeometry(0.16, 0.32, 4);

    const earL = new THREE.Mesh(earGeo, coatMat);
    earL.position.set(-0.32, 0.45, 0.02);
    earL.rotation.z = 0.22;
    earL.rotation.x = -0.15;
    this.headGroup.add(earL);

    const innerEarL = new THREE.Mesh(innerEarGeo, innerEarMat);
    innerEarL.position.set(-0.32, 0.44, -0.03);
    innerEarL.rotation.z = 0.22;
    innerEarL.rotation.x = -0.15;
    this.headGroup.add(innerEarL);

    const earR = new THREE.Mesh(earGeo, coatMat);
    earR.position.set(0.32, 0.45, 0.02);
    earR.rotation.z = -0.22;
    earR.rotation.x = -0.15;
    this.headGroup.add(earR);

    const innerEarR = new THREE.Mesh(innerEarGeo, innerEarMat);
    innerEarR.position.set(0.32, 0.44, -0.03);
    innerEarR.rotation.z = -0.22;
    innerEarR.rotation.x = -0.15;
    this.headGroup.add(innerEarR);

    // Muzzle / Snout
    const snoutGeo = new THREE.SphereGeometry(0.2, 12, 12);
    const snout = new THREE.Mesh(snoutGeo, bellyMat);
    snout.position.set(0, -0.08, -0.42);
    snout.scale.set(1.3, 0.9, 0.8);
    this.headGroup.add(snout);

    // Cute Pink Nose
    const noseGeo = new THREE.ConeGeometry(0.06, 0.06, 3);
    const nose = new THREE.Mesh(noseGeo, noseMat);
    nose.position.set(0, -0.02, -0.56);
    nose.rotation.x = -Math.PI / 2;
    this.headGroup.add(nose);

    // Expressive Eyes with Pupils
    const eyeGeo = new THREE.SphereGeometry(0.14, 12, 12);
    const pupilGeo = new THREE.SphereGeometry(0.09, 12, 12);
    const catchGeo = new THREE.SphereGeometry(0.04, 8, 8);
    const catchMat = new THREE.MeshBasicMaterial({ color: 0xffffff });

    // Eye Left
    const eyeL = new THREE.Mesh(eyeGeo, eyeMat);
    eyeL.position.set(-0.24, 0.1, -0.38);
    eyeL.scale.set(1.0, 1.25, 0.5);
    this.headGroup.add(eyeL);

    const pupilL = new THREE.Mesh(pupilGeo, pupilMat);
    pupilL.position.set(-0.24, 0.1, -0.44);
    pupilL.scale.set(0.6, 1.1, 0.3);
    this.headGroup.add(pupilL);

    const catchL = new THREE.Mesh(catchGeo, catchMat);
    catchL.position.set(-0.21, 0.15, -0.47);
    this.headGroup.add(catchL);

    // Eye Right
    const eyeR = new THREE.Mesh(eyeGeo, eyeMat);
    eyeR.position.set(0.24, 0.1, -0.38);
    eyeR.scale.set(1.0, 1.25, 0.5);
    this.headGroup.add(eyeR);

    const pupilR = new THREE.Mesh(pupilGeo, pupilMat);
    pupilR.position.set(0.24, 0.1, -0.44);
    pupilR.scale.set(0.6, 1.1, 0.3);
    this.headGroup.add(pupilR);

    const catchR = new THREE.Mesh(catchGeo, catchMat);
    catchR.position.set(0.27, 0.15, -0.47);
    this.headGroup.add(catchR);

    // 4 Articulated Legs
    const legGeo = new THREE.CylinderGeometry(0.12, 0.11, 0.55, 10);
    const pawGeo = new THREE.SphereGeometry(0.13, 8, 8);

    const createLeg = (x, z) => {
      const legGroup = new THREE.Group();
      legGroup.position.set(x, 0, z);

      const leg = new THREE.Mesh(legGeo, coatMat);
      leg.position.y = -0.28;
      leg.castShadow = true;
      legGroup.add(leg);

      const paw = new THREE.Mesh(pawGeo, bellyMat);
      paw.position.set(0, -0.52, -0.04);
      paw.scale.set(1.1, 0.8, 1.3);
      legGroup.add(paw);

      this.bodyGroup.add(legGroup);
      return legGroup;
    };

    this.legFL = createLeg(-0.3, -0.32);
    this.legFR = createLeg(0.3, -0.32);
    this.legBL = createLeg(-0.3, 0.32);
    this.legBR = createLeg(0.3, 0.32);

    // Multi-segmented Sinuous Tail
    this.tailGroup = new THREE.Group();
    this.tailGroup.position.set(0, 0.2, 0.45);
    this.bodyGroup.add(this.tailGroup);

    this.tailSegments = [];
    let currentParent = this.tailGroup;
    for (let i = 0; i < 4; i++) {
      const segGeo = new THREE.CylinderGeometry(0.09 - i * 0.015, 0.11 - i * 0.015, 0.28, 8);
      const segMesh = new THREE.Mesh(segGeo, coatMat);
      segMesh.position.y = 0.14;
      segMesh.rotation.x = 0.4;

      const segNode = new THREE.Group();
      if (i > 0) segNode.position.y = 0.24;
      segNode.add(segMesh);
      currentParent.add(segNode);
      this.tailSegments.push(segNode);
      currentParent = segNode;
    }

    // Ground-contact shadow disc (stays on receiving ground plane during bobs/jumps)
    const shadowGeo = new THREE.CircleGeometry(0.58, 24);
    const shadowMat = new THREE.MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.38,
      depthWrite: false
    });
    this.shadowDisc = new THREE.Mesh(shadowGeo, shadowMat);
    this.shadowDisc.rotation.x = -Math.PI / 2;
    this.shadowDisc.position.y = 0.03;
