				catRoot.position.set(dist, jumpHeight, 2.5);
				forwardAngle = avenueDirection > 0 ? Math.PI / 2 : -Math.PI / 2;
			} else {
				catRoot.position.set(-dist, jumpHeight, -2.5);
				forwardAngle = avenueDirection > 0 ? -Math.PI / 2 : Math.PI / 2;
			}
		} else {
			currentAngle += orbitSpeed / orbitRadius * delta * walkSpeed * 4;
			catRoot.position.x = Math.cos(currentAngle) * orbitRadius;
			catRoot.position.z = Math.sin(currentAngle) * orbitRadius;
			catRoot.position.y = jumpHeight;
			forwardAngle = currentAngle + Math.PI / 2;
		}
		catRoot.rotation.y = forwardAngle;
		const legPhase = time * 9 + index;
		const legSwing = Math.sin(legPhase) * .55;
		legFL.rotation.x = legSwing;
		legBR.rotation.x = legSwing;
		legFR.rotation.x = -legSwing;
		legBL.rotation.x = -legSwing;
		headPivot.position.y = 1.45 + Math.abs(Math.sin(legPhase * 2)) * .08;
		headPivot.rotation.z = Math.sin(time * 3 + index) * .08;
		tailPivot.rotation.y = Math.sin(time * 7 + index) * .45;
		tailMid.rotation.y = Math.sin(time * 7 + index + .5) * .55;
		bell.rotation.z = Math.sin(time * 12) * .35;
		if (isJumping) {
			jumpTimer += delta * 3.5;
			if (jumpTimer < Math.PI) {
				jumpHeight = Math.sin(jumpTimer) * 2.2;
				torso.rotation.x = Math.sin(jumpTimer) * .4;
			} else {
				jumpHeight = 0;
				isJumping = false;
				torso.rotation.x = 0;
			}
		} else jumpHeight = Math.abs(Math.sin(legPhase)) * .22;
		catRoot.position.y = jumpHeight;
		shadowDisc.position.y = .02 - jumpHeight / catRoot.scale.y;
		const shadowScale = Math.max(.55, 1 - jumpHeight * .12);
		shadowDisc.scale.set(shadowScale, shadowScale, 1);
	}
	function triggerJump() {
		isJumping = true;
		jumpTimer = 0;
	}
	return {
		root: catRoot,
		update,
		triggerJump
	};
}
/**
* Creates the entire animated Chibi Moru Cat village.
* Spawns >= 6 cats on load and manages their synchronized updates.
*/
function createCatVillage(scene, state) {
	const cats = [];
	const initialCatCount = 7;
	for (let i = 0; i < initialCatCount; i++) {
		const cat = createMoruCat(i);
		scene.add(cat.root);
		cats.push(cat);
	}
	state.catCount = cats.length;
	function spawnCat() {
		const idx = cats.length;
		const spawnAngle = Math.random() * Math.PI * 2;
		const spawnDist = 18 + Math.random() * 8;
		const newCat = createMoruCat(idx, new THREE.Vector3(Math.cos(spawnAngle) * spawnDist, 0, Math.sin(spawnAngle) * spawnDist));
		scene.add(newCat.root);
		cats.push(newCat);
		state.catCount = cats.length;
		newCat.triggerJump();
		return newCat;
	}
	function triggerForgeJump() {
		cats.forEach((cat) => cat.triggerJump());
	}
	function update(delta, time, isSpinning) {
		if (!isSpinning) return;
		cats.forEach((cat) => cat.update(delta, time));
	}
	function getActiveCat() {
		return cats[0] ? cats[0].root : null;
	}
	return {
		cats,
		spawnCat,
		triggerForgeJump,
		update,
		getActiveCat
	};
}
//#endregion
