      const dist = 36 + avenueProgress * 40;
      if (avenueIdx === 0) catRoot.position.set(0, 0, dist);
      else if (avenueIdx === 1) catRoot.position.set(0, 0, -dist);
      else if (avenueIdx === 2) catRoot.position.set(dist, 0, 0);
      else catRoot.position.set(-dist, 0, 0);
    } else {
      // Plaza circle patrol
      catRoot.position.set(
        Math.cos(currentAngle) * orbitRadius,
        0,
        Math.sin(currentAngle) * orbitRadius
      );
    }
  }

  // Locomotion update function
  function update(delta, time) {
    // 1. Move cat in world coordinates
    const walkSpeed = 3.6;
    let forwardAngle = 0;

    if (pathType === 2) {
      // Trot along avenue
      avenueProgress += avenueDirection * delta * (0.08 * walkSpeed);
      if (avenueProgress > 1.0) {
        avenueProgress = 1.0;
        avenueDirection = -1;
      } else if (avenueProgress < 0.0) {
        avenueProgress = 0.0;
        avenueDirection = 1;
      }

      const dist = 32 + avenueProgress * 45;
      if (avenueIdx === 0) {
        catRoot.position.set(2.5, jumpHeight, dist);
        forwardAngle = avenueDirection > 0 ? 0 : Math.PI;
      } else if (avenueIdx === 1) {
        catRoot.position.set(-2.5, jumpHeight, -dist);
        forwardAngle = avenueDirection > 0 ? Math.PI : 0;
      } else if (avenueIdx === 2) {
        catRoot.position.set(dist, jumpHeight, 2.5);
        forwardAngle = avenueDirection > 0 ? Math.PI / 2 : -Math.PI / 2;
      } else {
        catRoot.position.set(-dist, jumpHeight, -2.5);
        forwardAngle = avenueDirection > 0 ? -Math.PI / 2 : Math.PI / 2;
      }
    } else {
      // Orbit around the central forge plaza
      currentAngle += (orbitSpeed / orbitRadius) * delta * walkSpeed * 4.0;
      catRoot.position.x = Math.cos(currentAngle) * orbitRadius;
      catRoot.position.z = Math.sin(currentAngle) * orbitRadius;
      catRoot.position.y = jumpHeight;
      // Tangent angle
      forwardAngle = currentAngle + Math.PI / 2;
    }

    // Set heading rotation
    catRoot.rotation.y = forwardAngle;

    // 2. Quadruped leg swinging (diagonal trot gait)
    const legPhase = time * 9.0 + index;
    const legSwing = Math.sin(legPhase) * 0.55;

    legFL.rotation.x = legSwing;
    legBR.rotation.x = legSwing;
    legFR.rotation.x = -legSwing;
    legBL.rotation.x = -legSwing;

    // 3. Cute head bob & tail wag
    headPivot.position.y = 1.45 + Math.abs(Math.sin(legPhase * 2)) * 0.08;
    headPivot.rotation.z = Math.sin(time * 3.0 + index) * 0.08;

    tailPivot.rotation.y = Math.sin(time * 7.0 + index) * 0.45;
    tailMid.rotation.y = Math.sin(time * 7.0 + index + 0.5) * 0.55;

    // 4. Bell jingle
    bell.rotation.z = Math.sin(time * 12.0) * 0.35;

    // 5. Jump logic (celebration / strike hop)
    if (isJumping) {
      jumpTimer += delta * 3.5;
      if (jumpTimer < Math.PI) {
        jumpHeight = Math.sin(jumpTimer) * 2.2;
        torso.rotation.x = Math.sin(jumpTimer) * 0.4;
      } else {
        jumpHeight = 0;
        isJumping = false;
        torso.rotation.x = 0;
      }
    } else {
      // Normal cute trot hop bounce
      jumpHeight = Math.abs(Math.sin(legPhase)) * 0.22;
    }

    // Keep cat root height and ground-contact shadow disc locked to the ground plane
    catRoot.position.y = jumpHeight;
    shadowDisc.position.y = 0.02 - jumpHeight / catRoot.scale.y;
    const shadowScale = Math.max(0.55, 1.0 - jumpHeight * 0.12);
    shadowDisc.scale.set(shadowScale, shadowScale, 1.0);
  }

  function triggerJump() {
    isJumping = true;
    jumpTimer = 0;
  }

  return {
    root: catRoot,
    update,
    triggerJump
  };
}

/**
 * Creates the entire animated Chibi Moru Cat village.
 * Spawns >= 6 cats on load and manages their synchronized updates.
 */
export function createCatVillage(scene, state) {
  const cats = [];
  const initialCatCount = 7; // Ensures >= 6 cats on load

  for (let i = 0; i < initialCatCount; i++) {
    const cat = createMoruCat(i);
    scene.add(cat.root);
    cats.push(cat);
  }

  state.catCount = cats.length;

  function spawnCat() {
    const idx = cats.length;
    // Spawn near the plaza entrance
    const spawnAngle = Math.random() * Math.PI * 2;
    const spawnDist = 18 + Math.random() * 8;
    const pos = new THREE.Vector3(
      Math.cos(spawnAngle) * spawnDist,
      0,
      Math.sin(spawnAngle) * spawnDist
    );

    const newCat = createMoruCat(idx, pos);
    scene.add(newCat.root);
    cats.push(newCat);
    state.catCount = cats.length;

    // Give new cat an introductory jump
    newCat.triggerJump();
    return newCat;
  }

  function triggerForgeJump() {
    cats.forEach(cat => cat.triggerJump());
  }

  function update(delta, time, isSpinning) {
    if (!isSpinning) return;
    cats.forEach(cat => cat.update(delta, time));
  }

  function getActiveCat() {
    return cats[0] ? cats[0].root : null;
  }

  return {
    cats,
    spawnCat,
    triggerForgeJump,
    update,
    getActiveCat
  };
}




