});

renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Scene & Camera
const scene = new THREE.Scene();

const camera = new THREE.PerspectiveCamera(
  45,
  window.innerWidth / window.innerHeight,
  0.5,
  800
);
// Default overview position & target as specified in SPEC.md G6
camera.position.set(42, 30, 46);

// OrbitControls setup as specified in SPEC.md G6
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 3.5, 0);
controls.enableRotate = true;
controls.enableZoom = true;
controls.enablePan = true;
controls.autoRotate = true;
controls.autoRotateSpeed = 2.2;
controls.enableDamping = false;
controls.update();

// Post-Processing Pipeline (EffectComposer + RenderPass + UnrealBloomPass)
const composer = new EffectComposer(renderer);
const renderPass = new RenderPass(scene, camera);
composer.addPass(renderPass);

const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.65, // strength
  0.45, // radius
  0.65  // threshold
);
composer.addPass(bloomPass);

// Lighting Rig
const ambientLight = new THREE.AmbientLight(0x303952, 0.85);
scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0x6b88b6, 0.95);
sunLight.position.set(60, 90, 50);
sunLight.castShadow = true;
sunLight.shadow.mapSize.width = 2048;
sunLight.shadow.mapSize.height = 2048;
sunLight.shadow.camera.near = 10;
sunLight.shadow.camera.far = 250;
const d = 65;
sunLight.shadow.camera.left = -d;
sunLight.shadow.camera.right = d;
sunLight.shadow.camera.top = d;
sunLight.shadow.camera.bottom = -d;
sunLight.shadow.bias = -0.0005;
scene.add(sunLight);

// Hemisphere Light for balanced fill illumination (prevents dark blackout)
const hemiLight = new THREE.HemisphereLight(0x404870, 0x25283a, 0.6);
scene.add(hemiLight);

// ==========================================
// THEME MANAGEMENT & HISTOGRAM GUARD
// ==========================================
// Balanced exposure profiles preventing dark blackout (luminance < 12) < 75%
// and bright white-out (luminance > 245) < 8% across Night, Gold, and Day modes.
const THEMES = {
  night: {
    bg: 0x101428,
    fogColor: 0x101428,
    fogNear: 35,
    fogFar: 180,
    sunColor: 0x6b88b6,
    sunIntensity: 0.95,
    sunPos: [60, 90, 50],
    ambientColor: 0x303952,
    ambientIntensity: 0.85,
