    fogFar: 185,
    sunColor: 0xffa534,
    sunIntensity: 1.25,
    sunPos: [-85, 38, 65],
    ambientColor: 0x553322,
    ambientIntensity: 0.85,
    hemiSky: 0x7c4d29,
    hemiGround: 0x3d2414,
