  },
  day: {
    bg: 0x5b8bb8, // Crisp azure sky (not blown out)
    fogColor: 0x5583ae,
    fogNear: 40,
    fogFar: 200,
    sunColor: 0xffffff,
    sunIntensity: 1.30,
    sunPos: [55, 115, 45],
    ambientColor: 0x607d8b,
    ambientIntensity: 0.80,
    hemiSky: 0x82b1ff,
    hemiGround: 0x455a64,
    hemiIntensity: 0.7,
    exposure: 0.95,
    bloomStrength: 0.35,
    bloomThreshold: 0.85,
