  }
};

function applyTheme(themeName) {
  const t = THEMES[themeName] || THEMES.night;
  state.theme = themeName;
  state.disposedCount = (state.disposedCount || 0) + 1;

  // Update URL search param cleanly without full page refresh
  const url = new URL(window.location.href);
  url.searchParams.set('theme', themeName);
  window.history.replaceState(null, '', url.toString());

  // Apply visual theme parameters
  scene.background = new THREE.Color(t.bg);
  scene.fog = new THREE.Fog(t.fogColor, t.fogNear, t.fogFar);

  sunLight.color.setHex(t.sunColor);
  sunLight.intensity = t.sunIntensity;
  if (t.sunPos) {
    sunLight.position.set(t.sunPos[0], t.sunPos[1], t.sunPos[2]);
    sunLight.updateMatrixWorld();
  }

  ambientLight.color.setHex(t.ambientColor);
  ambientLight.intensity = t.ambientIntensity;

  hemiLight.color.setHex(t.hemiSky);
  hemiLight.groundColor.setHex(t.hemiGround);
  hemiLight.intensity = t.hemiIntensity;

  renderer.toneMappingExposure = t.exposure;
  bloomPass.strength = t.bloomStrength;
  bloomPass.threshold = t.bloomThreshold;
  bloomPass.radius = t.bloomRadius;

  // Update UI button highlights
  ['night', 'gold', 'day'].forEach(m => {
    const btn = document.getElementById(`mode-${m}`);
    if (btn) {
      if (m === themeName) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    }
  });

  if (!state.spinning) {
    composer.render();
  }
}

// Initial theme apply
applyTheme(initialTheme);

// ==========================================
// BUILD SCENE ENTITIES
// ==========================================
// 1. Build City Skyline, Roads, Trees, and Streetlamps
const city = createCity(scene);
state.buildingCount = city.buildings.length;
state.lampCount = city.streetlamps.length;
state.treeCount = city.trees.length;

// 2. Build Chibi Moru Cat Village
let catVillage = null;
const forge = createForge(scene, state, () => {
  // Callback when hammer strikes ingot
  if (catVillage) {
    catVillage.triggerForgeJump();
  }
});

catVillage = createCatVillage(scene, state);

// Compute total triangles in scene
function countSceneTriangles(root) {
  let tris = 0;
  root.traverse(obj => {
    if (obj.isMesh && obj.geometry) {
      if (obj.geometry.index) {
        tris += obj.geometry.index.count / 3;
      } else if (obj.geometry.attributes.position) {
        tris += obj.geometry.attributes.position.count / 3;
      }
    }
  });
  return Math.round(tris);
}

state.triangles = countSceneTriangles(scene);

// Expose window.__app as required by G3
window.__app = {
  scene,
  camera,
  renderer,
  composer,
  state
};

// ==========================================
// UI CONTROLS & EVENT LISTENERS
// ==========================================
const fpsHud = document.getElementById('fps-hud');

// Camera Preset Switchers
const camOverviewBtn = document.getElementById('cam-overview');
const camIsoBtn = document.getElementById('cam-iso');
const camStreetBtn = document.getElementById('cam-street');
const camFollowCatBtn = document.getElementById('cam-follow-cat');

function updateCameraMode(mode) {
  state.cameraMode = mode;
  [camOverviewBtn, camIsoBtn, camStreetBtn, camFollowCatBtn].forEach(b => b?.classList.remove('active'));

  if (mode === 'overview') {
    camOverviewBtn?.classList.add('active');
    camera.position.set(42, 30, 46);
    controls.target.set(0, 3.5, 0);
    controls.enabled = true;
    controls.autoRotate = state.spinning;
    controls.update();
  } else if (mode === 'iso') {
    camIsoBtn?.classList.add('active');
    camera.position.set(48, 42, 48);
    controls.target.set(0, 3.5, 0);
    controls.enabled = true;
    controls.autoRotate = false;
    controls.update();
  } else if (mode === 'street') {
    camStreetBtn?.classList.add('active');
    camera.position.set(0, 4.5, 26);
    controls.target.set(0, 3.5, 0);
    controls.enabled = true;
    controls.autoRotate = false;
    controls.update();
  } else if (mode === 'follow') {
    camFollowCatBtn?.classList.add('active');
    controls.autoRotate = false;
    controls.enabled = false;
  }

  if (!state.spinning) {
    composer.render();
  }
}

camOverviewBtn?.addEventListener('click', () => updateCameraMode('overview'));
camIsoBtn?.addEventListener('click', () => updateCameraMode('iso'));
camStreetBtn?.addEventListener('click', () => updateCameraMode('street'));
