  });

  // Streetlamp geometries
  const poleGeo = new THREE.CylinderGeometry(0.12, 0.16, 5.2, 12);
  const armGeo = new THREE.BoxGeometry(1.2, 0.12, 0.12);
  const lanternGeo = new THREE.CylinderGeometry(0.3, 0.15, 0.5, 12);
  const bulbGeo = new THREE.SphereGeometry(0.24, 16, 16);
  const poolDiscGeo = new THREE.CircleGeometry(3.6, 24);

  for (let i = 0; i < lampCount; i++) {
    const lampGroup = new THREE.Group();
    lampGroup.name = `streetlamp_${i}`;

    // Vertical pole
    const pole = new THREE.Mesh(poleGeo, lampPoleMat);
    pole.position.y = 2.6;
    lampGroup.add(pole);

    // Horizontal arm
    const arm = new THREE.Mesh(armGeo, lampPoleMat);
    arm.position.set(0.5, 5.1, 0);
    lampGroup.add(arm);

    // Lantern fixture
    const lantern = new THREE.Mesh(lanternGeo, lampPoleMat);
    lantern.position.set(1.0, 4.8, 0);
    lampGroup.add(lantern);

    // Glowing bulb
    const bulb = new THREE.Mesh(bulbGeo, bulbGlowMat);
    bulb.position.set(1.0, 4.65, 0);
    lampGroup.add(bulb);

    // Ground light pool disc beneath the bulb
    const poolDisc = new THREE.Mesh(poolDiscGeo, poolDiscMat);
    poolDisc.rotation.x = -Math.PI / 2;
    poolDisc.position.set(1.0, 0.05, 0);
    lampGroup.add(poolDisc);

    // Position lamps along plaza ring & avenues
    let lx, lz, rotY = 0;
    if (i < 40) {
      // Plaza circle lamps
      const angle = (i / 40) * Math.PI * 2;
      const radius = 24.5;
      lx = Math.cos(angle) * radius;
      lz = Math.sin(angle) * radius;
      rotY = angle + Math.PI; // Point lantern inward toward plaza
    } else {
      // Avenue streetlamps along curbs
      const aveIdx = (i - 40) % 4;
      const stepAlong = 36 + Math.floor((i - 40) / 4) * 6.0;
      const side = ((i % 2 === 0) ? 1 : -1) * 7.2;

      if (aveIdx === 0) { lx = side; lz = stepAlong; rotY = (side > 0 ? -Math.PI / 2 : Math.PI / 2); }
      else if (aveIdx === 1) { lx = side; lz = -stepAlong; rotY = (side > 0 ? -Math.PI / 2 : Math.PI / 2); }
      else if (aveIdx === 2) { lx = stepAlong; lz = side; rotY = (side > 0 ? 0 : Math.PI); }
      else { lx = -stepAlong; lz = side; rotY = (side > 0 ? 0 : Math.PI); }
    }

    lampGroup.position.set(lx, 0, lz);
    lampGroup.rotation.y = rotY;
    cityGroup.add(lampGroup);
    streetlamps.push(lampGroup);
  }

  // Animation update for blinking rooftop beacons
  function update(time) {
    beaconMeshes.forEach(b => {
      // Smooth blinking cycle
      const blink = (Math.sin(time * 4.0 + b.offset) + 1.0) * 0.5;
      b.mesh.visible = blink > 0.35;
    });
  }

  return {
    group: cityGroup,
    buildings,
    trees,
    streetlamps,
    update
  };
}




