/**
 * Streetlamp Ground Light Pool Disc Texture (soft radial glow).
 */
export function createLightPoolTexture(colorHex = '#ffe082') {
  const size = 256;
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');
  const cx = size / 2;
  const cy = size / 2;

  const grad = ctx.createRadialGradient(cx, cy, 4, cx, cy, size / 2);
  grad.addColorStop(0, colorHex);
  grad.addColorStop(0.3, 'rgba(255, 215, 120, 0.45)');
  grad.addColorStop(0.65, 'rgba(255, 180, 80, 0.15)');
  grad.addColorStop(1, 'rgba(0, 0, 0, 0)');

  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

/**
 * Molten Magma Texture for the forge hearth.
 */
export function createMagmaTexture() {
  const size = 512;
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');

  // Intense volcanic lava background
  ctx.fillStyle = '#ff3300';
  ctx.fillRect(0, 0, size, size);

  // Layered glowing magma veins
  for (let i = 0; i < 40; i++) {
    const grad = ctx.createRadialGradient(
      Math.random() * size, Math.random() * size, 10,
      Math.random() * size, Math.random() * size, 120
    );
    grad.addColorStop(0, '#ffff66');
    grad.addColorStop(0.3, '#ff7700');
    grad.addColorStop(0.7, '#cc1100');
    grad.addColorStop(1, '#330500');

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(Math.random() * size, Math.random() * size, Math.random() * 80 + 40, 0, Math.PI * 2);
    ctx.fill();
  }

  // Floating dark volcanic crust cracks
  ctx.strokeStyle = '#220800';
  ctx.lineWidth = 14;
  for (let i = 0; i < 15; i++) {
    ctx.beginPath();
    ctx.moveTo(Math.random() * size, Math.random() * size);
    for (let j = 0; j < 4; j++) {
      ctx.lineTo(Math.random() * size, Math.random() * size);
    }
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

/**
 * Helipad Roof Texture with 'H' insignia and neon landing ring.
 */
export function createHelipadTexture() {
  const size = 512;
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');
  const cx = size / 2;
  const cy = size / 2;

  // Dark rooftop surface
  ctx.fillStyle = '#181b26';
  ctx.fillRect(0, 0, size, size);

  // Outer safety perimeter
  ctx.strokeStyle = '#ffd166';
  ctx.lineWidth = 8;
  ctx.strokeRect(20, 20, size - 40, size - 40);

  // Bold landing circle
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 12;
  ctx.beginPath();
  ctx.arc(cx, cy, 180, 0, Math.PI * 2);
  ctx.stroke();

  // Bold 'H' symbol
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 220px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('H', cx, cy + 8);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}




