var hudFps = document.getElementById("hud-fps");
var hudCats = document.getElementById("hud-cats");
var hudHeat = document.getElementById("hud-heat");
var hudStrikes = document.getElementById("hud-strikes");
function animate() {
	requestAnimationFrame(animate);
	const now = performance.now();
	let dt = (now - lastTime) / 1e3;
	lastTime = now;
	if (dt > .1) dt = .1;
	frameCount++;
	if (now - lastFpsUpdateTime >= 400) {
		state.fps = Math.round(frameCount * 1e3 / (now - lastFpsUpdateTime));
		frameCount = 0;
		lastFpsUpdateTime = now;
		if (hudFps) hudFps.textContent = `${state.fps} FPS`;
		if (hudCats) hudCats.textContent = `${state.cats.length} Cats`;
		if (hudHeat) hudHeat.textContent = `${Math.round(state.forgeHeat).toLocaleString()} °C`;
		if (hudStrikes) hudStrikes.textContent = `${state.forgeStrikes} Hits`;
	}
	if (!state.isPaused) {
		if (state.forgeHeat > 1200) state.forgeHeat = Math.max(1200, state.forgeHeat - dt * 65);
		holoRing1.rotation.z += dt * .8;
		holoRing2.rotation.x += dt * .6;
		if (isStriking) {
			strikeProgress += dt * 3.8;
			if (strikeProgress < .25) hammerArmGroup.rotation.z = .55 + strikeProgress * 3.5;
			else if (strikeProgress < .5) {
				const p = (strikeProgress - .25) / .25;
				hammerArmGroup.rotation.z = (1 - p) * 1.4;
			} else if (strikeProgress < 1) {
				const p = (strikeProgress - .5) / .5;
				hammerArmGroup.rotation.z = Math.sin(p * Math.PI) * .25 + (1 - p) * .1 + p * .55;
			} else {
				isStriking = false;
				hammerArmGroup.rotation.z = .55;
			}
		} else hammerArmGroup.rotation.z = .55 + Math.sin(now * .002) * .06;
		state.cats.forEach((cat) => cat.update(dt));
		drones.forEach((d) => {
			d.userData.angle += d.userData.speed * dt * .4;
			const dx = Math.cos(d.userData.angle) * d.userData.radius;
			const dz = Math.sin(d.userData.angle) * d.userData.radius;
			d.position.set(dx, d.userData.height, dz);
			d.rotation.y = -d.userData.angle - Math.PI / 2;
		});
		if (sparkMat.opacity > .01) {
			const posArr = sparkGeo.attributes.position.array;
			let anyAlive = false;
			for (let i = 0; i < SPARK_COUNT; i++) if (sparkLifetimes[i] > 0) {
				anyAlive = true;
				sparkLifetimes[i] -= dt * 1.6;
				sparkVelocities[i].y -= 24 * dt;
				posArr[i * 3] += sparkVelocities[i].x * dt;
				posArr[i * 3 + 1] += sparkVelocities[i].y * dt;
				posArr[i * 3 + 2] += sparkVelocities[i].z * dt;
				if (posArr[i * 3 + 1] < 1.15) {
					posArr[i * 3 + 1] = 1.15;
					sparkVelocities[i].y *= -.45;
					sparkVelocities[i].x *= .7;
					sparkVelocities[i].z *= .7;
				}
			}
			sparkGeo.attributes.position.needsUpdate = true;
			if (!anyAlive) sparkMat.opacity = Math.max(0, sparkMat.opacity - dt * 2);
		}
		if (shockwaveActive) {
			shockwaveScale += dt * 16;
			shockwave.scale.set(shockwaveScale, shockwaveScale, 1);
			shockwaveMat.opacity -= dt * 2.2;
			if (shockwaveMat.opacity <= 0) {
				shockwaveActive = false;
				shockwaveMat.opacity = 0;
			}
		}
		if (forgeLight.intensity > 4.2) forgeLight.intensity = Math.max(4.2, forgeLight.intensity - dt * 18);
		if (anvilRuneLight.intensity > 2.5) anvilRuneLight.intensity = Math.max(2.5, anvilRuneLight.intensity - dt * 10);
		for (let i = hearts.length - 1; i >= 0; i--) {
			const h = hearts[i];
			h.userData.life -= dt * 1.4;
			h.position.addScaledVector(h.userData.vel, dt);
			h.scale.multiplyScalar(.98);
			h.material.opacity = Math.max(0, h.userData.life);
			if (h.userData.life <= 0) {
				scene.remove(h);
				hearts.splice(i, 1);
			}
		}
	}
	if (currentCamMode === "follow-cat") {
		const activeCat = state.cats[state.activeCatIndex] || state.cats[0];
		if (activeCat) {
			const catPos = activeCat.pos;
			const heading = activeCat.heading;
			const offsetDist = 6.5;
			const targetCamPos = new THREE.Vector3(catPos.x - Math.sin(heading) * offsetDist, catPos.y + 3.2, catPos.z - Math.cos(heading) * offsetDist);
			const lookTarget = new THREE.Vector3(catPos.x, catPos.y + 1.2, catPos.z);
			camera.position.lerp(targetCamPos, dt * 5.5);
			controls.target.lerp(lookTarget, dt * 6.5);
		}
	} else if (isTransitioningCam) {
		camLerpProgress += dt * 2.2;
		const t = Math.min(1, camLerpProgress);
		const ease = 1 - Math.pow(1 - t, 3);
		camera.position.lerpVectors(camStartPos, camEndPos, ease);
		controls.target.lerpVectors(camStartTarget, camEndTarget, ease);
		if (t >= 1) isTransitioningCam = false;
	}
	if (cameraShakeTime > 0) {
		cameraShakeTime -= dt;
		const shakeX = (Math.random() - .5) * cameraShakeIntensity;
		const shakeY = (Math.random() - .5) * cameraShakeIntensity;
		const shakeZ = (Math.random() - .5) * cameraShakeIntensity;
		camera.position.add(new THREE.Vector3(shakeX, shakeY, shakeZ));
		cameraShakeIntensity = Math.max(0, cameraShakeIntensity - dt * 3.5);
	}
	controls.update();
	renderer.render(scene, camera);
}
animate();
//#endregion

