// ====== src/main.js (64550 bytes) ======
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

/* ==========================================================================
   MORU 3D NEON FORGE CITY & ANIMATED CAT VILLAGE
   Interactive 3D WebGL Application
   ========================================================================== */

// --- Audio Synthesizer (Zero external dependencies) ---
class CyberAudioEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
  }

  init() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  playStrike() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;

    // Heavy bass thump
    const oscBass = this.ctx.createOscillator();
    const gainBass = this.ctx.createGain();
    oscBass.type = 'triangle';
    oscBass.frequency.setValueAtTime(140, t);
    oscBass.frequency.exponentialRampToValueAtTime(35, t + 0.35);
    gainBass.gain.setValueAtTime(0.9, t);
    gainBass.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
    oscBass.connect(gainBass);
    gainBass.connect(this.ctx.destination);
    oscBass.start(t);
    oscBass.stop(t + 0.35);

    // High metallic anvil ring (FM metallic ping)
    const carrier = this.ctx.createOscillator();
    const carrierGain = this.ctx.createGain();
    carrier.type = 'sine';
    carrier.frequency.setValueAtTime(1280, t);
    carrier.frequency.exponentialRampToValueAtTime(1150, t + 1.2);

    // Metallic overtone harmonic
    const overtone = this.ctx.createOscillator();
    const overtoneGain = this.ctx.createGain();
    overtone.type = 'sine';
    overtone.frequency.setValueAtTime(2560, t);
    overtone.frequency.exponentialRampToValueAtTime(2400, t + 0.8);

    carrierGain.gain.setValueAtTime(0.6, t);
    carrierGain.gain.exponentialRampToValueAtTime(0.001, t + 1.4);

    overtoneGain.gain.setValueAtTime(0.35, t);
    overtoneGain.gain.exponentialRampToValueAtTime(0.001, t + 0.9);

    carrier.connect(carrierGain);
    carrierGain.connect(this.ctx.destination);
    overtone.connect(overtoneGain);
    overtoneGain.connect(this.ctx.destination);

    carrier.start(t);
    carrier.stop(t + 1.4);
    overtone.start(t);
    overtone.stop(t + 0.9);

    // Impact noise burst
    const bufferSize = this.ctx.sampleRate * 0.15;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (this.ctx.sampleRate * 0.03));
    }
    const noiseSource = this.ctx.createBufferSource();
    noiseSource.buffer = buffer;
    const noiseFilter = this.ctx.createBiquadFilter();
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.setValueAtTime(3200, t);
    noiseFilter.Q.setValueAtTime(2.0, t);

    const noiseGain = this.ctx.createGain();
    noiseGain.gain.setValueAtTime(0.5, t);
    noiseGain.gain.exponentialRampToValueAtTime(0.01, t + 0.15);

    noiseSource.connect(noiseFilter);
    noiseFilter.connect(noiseGain);
    noiseGain.connect(this.ctx.destination);
    noiseSource.start(t);
  }

  playMeow() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    // Classic meow pitch inflection (rise then gentle fall)
    osc.frequency.setValueAtTime(450, t);
    osc.frequency.exponentialRampToValueAtTime(820, t + 0.12);
    osc.frequency.exponentialRampToValueAtTime(560, t + 0.38);

    // Subtle cute vibrato
    const vibrato = this.ctx.createOscillator();
    const vibratoGain = this.ctx.createGain();
    vibrato.frequency.setValueAtTime(6.5, t);
    vibratoGain.gain.setValueAtTime(18, t);
    vibrato.connect(osc.frequency);
    vibrato.start(t);
    vibrato.stop(t + 0.42);

    gain.gain.setValueAtTime(0.01, t);
    gain.gain.linearRampToValueAtTime(0.25, t + 0.06);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.42);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(t);
    osc.stop(t + 0.42);
  }

  playSpawn() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;
    const freqs = [523.25, 659.25, 783.99, 1046.50]; // C5, E5, G5, C6 arpeggio
    freqs.forEach((f, idx) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(f, t + idx * 0.05);

      gain.gain.setValueAtTime(0.18, t + idx * 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, t + idx * 0.05 + 0.28);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(t + idx * 0.05);
      osc.stop(t + idx * 0.05 + 0.28);
    });
  }
}

const audio = new CyberAudioEngine();

// --- Texture Generators for Cyber Skyline ---
function createCyberWindowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');

  // Dark building facade background
  ctx.fillStyle = '#0b0f19';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Structural vertical beams
  ctx.strokeStyle = '#141d2e';
  ctx.lineWidth = 2;
  for (let x = 0; x < canvas.width; x += 16) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, canvas.height);
    ctx.stroke();
  }

  // Windows grid
  const cols = 12;
  const rows = 32;
  const w = canvas.width / cols;
  const h = canvas.height / rows;

  const windowColors = [
    '#00f0ff', // Cyber cyan
    '#ffaa00', // Warm amber
    '#ff2a85', // Neon pink
    '#c8e6ff', // Cool white
    '#00ffaa'  // Mint green
  ];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const isLit = Math.random() < 0.62;
      if (isLit) {
        const color = windowColors[Math.floor(Math.random() * windowColors.length)];
        const alpha = 0.5 + Math.random() * 0.5;
        ctx.fillStyle = color;
        ctx.globalAlpha = alpha;
        ctx.fillRect(c * w + 3, r * h + 3, w - 6, h - 5);
        ctx.globalAlpha = 1.0;
      } else {
        ctx.fillStyle = '#060910';
        ctx.fillRect(c * w + 3, r * h + 3, w - 6, h - 5);
      }
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  return texture;
}

function createBillboardTexture(title, subtitle, accentColor) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');

  // Background
  ctx.fillStyle = '#050812';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Outer glowing border
  ctx.strokeStyle = accentColor;
  ctx.lineWidth = 8;
  ctx.strokeRect(8, 8, canvas.width - 16, canvas.height - 16);

  // Inner border
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.strokeRect(18, 18, canvas.width - 36, canvas.height - 36);

  // Scanlines
  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
  for (let y = 0; y < canvas.height; y += 4) {
    ctx.fillRect(0, y, canvas.width, 2);
  }

  // Text title
  ctx.fillStyle = accentColor;
  ctx.font = 'bold 54px sans-serif';
  ctx.textAlign = 'center';
  ctx.shadowColor = accentColor;
  ctx.shadowBlur = 18;
  ctx.fillText(title, canvas.width / 2, 115);

  // Text subtitle
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 24px monospace';
  ctx.shadowBlur = 8;
  ctx.fillText(subtitle, canvas.width / 2, 175);

  const texture = new THREE.CanvasTexture(canvas);
  return texture;
}

// --- Application Core & State ---
const canvas = document.getElementById('webgl-canvas');
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: 'high-performance'
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x060814);
scene.fog = new THREE.FogExp2(0x060814, 0.0085);

const camera = new THREE.PerspectiveCamera(48, window.innerWidth / window.innerHeight, 0.5, 450);
camera.position.set(0, 85, 115);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxPolarAngle = Math.PI / 2 - 0.04; // Don't clip under ground
controls.minDistance = 5;
controls.maxDistance = 240;
controls.target.set(0, 4, 0);

// Global State
const state = {
  cats: [],
  activeCatIndex: 0,
  theme: 'night',
  cameraMode: 'overview',
  isPaused: false,
  forgeHeat: 1200,
  forgeStrikes: 0,
  fps: 60,
  spawnCat: null,
  strikeForge: null,
  setCameraMode: null,
  setTheme: null,
  togglePause: null,
  selectCat: null
};

// Expose on window for evaluation and inspection
window.__app = { scene, camera, renderer, state };

// --- Lighting & Atmosphere Themes ---
const ambientLight = new THREE.AmbientLight(0x182442, 1.2);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0x4070cc, 1.4);
dirLight.position.set(60, 90, 50);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 10;
dirLight.shadow.camera.far = 280;
dirLight.shadow.camera.left = -90;
dirLight.shadow.camera.right = 90;
dirLight.shadow.camera.top = 90;
dirLight.shadow.camera.bottom = -90;
dirLight.shadow.bias = -0.0005;
scene.add(dirLight);

// Central Forge Plaza Point Light
const forgeLight = new THREE.PointLight(0xff6600, 4.0, 45, 1.8);
forgeLight.position.set(0, 5.5, 0);
forgeLight.castShadow = true;
scene.add(forgeLight);

// Glowing Anvil Light
const anvilRuneLight = new THREE.PointLight(0x00f0ff, 2.5, 25, 2);
anvilRuneLight.position.set(0, 3.8, 0);
scene.add(anvilRuneLight);

// Starfield particles for night mode
const starGeo = new THREE.BufferGeometry();
const starCount = 1200;
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount * 3; i += 3) {
  const rad = 180 + Math.random() * 80;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(Math.random() * 0.9 + 0.1);
  starPos[i] = rad * Math.sin(phi) * Math.cos(theta);
  starPos[i + 1] = rad * Math.cos(phi);
  starPos[i + 2] = rad * Math.sin(phi) * Math.sin(theta);
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 1.2,
  transparent: true,
  opacity: 0.85
});
const starField = new THREE.Points(starGeo, starMat);
scene.add(starField);

// Atmosphere Theme Switcher
function applyTheme(themeName) {
  state.theme = themeName;
  document.querySelectorAll('.btn-toggle[id^="mode-"]').forEach(btn => btn.classList.remove('active'));
  const activeBtn = document.getElementById(`mode-${themeName}`);
  if (activeBtn) activeBtn.classList.add('active');

  if (themeName === 'night') {
    scene.background.setHex(0x060814);
    scene.fog.color.setHex(0x060814);
    scene.fog.density = 0.0085;
    ambientLight.color.setHex(0x182442);
    ambientLight.intensity = 1.1;
    dirLight.color.setHex(0x3860bb);
    dirLight.intensity = 1.3;
    dirLight.position.set(60, 90, 50);
    forgeLight.color.setHex(0xff5500);
    forgeLight.intensity = 4.2;
    anvilRuneLight.color.setHex(0x00f0ff);
    starField.visible = true;
  } else if (themeName === 'gold') {
    scene.background.setHex(0x281208);
    scene.fog.color.setHex(0x281208);
    scene.fog.density = 0.008;
    ambientLight.color.setHex(0x3d2112);
    ambientLight.intensity = 1.3;
    dirLight.color.setHex(0xffaa44);
    dirLight.intensity = 2.4;
    dirLight.position.set(75, 45, -30); // Low sunset angle
    forgeLight.color.setHex(0xff3700);
    forgeLight.intensity = 5.0;
    anvilRuneLight.color.setHex(0xffaa00);
    starField.visible = false;
  } else if (themeName === 'day') {
    scene.background.setHex(0x7db3e8);
    scene.fog.color.setHex(0xaecde8);
    scene.fog.density = 0.0055;
    ambientLight.color.setHex(0x8fa3b8);
    ambientLight.intensity = 1.4;
    dirLight.color.setHex(0xfffaec);
    dirLight.intensity = 2.2;
    dirLight.position.set(40, 110, 30);
    forgeLight.color.setHex(0xff7722);
    forgeLight.intensity = 3.0;
    anvilRuneLight.color.setHex(0x00d4ff);
    starField.visible = false;
  }
}
state.setTheme = applyTheme;

// --- Central Plaza & Ground Layout ---
const cityGroup = new THREE.Group();
