// Camera shake state
let cameraShakeTime = 0;
let cameraShakeIntensity = 0;

// Hammer strike animation state
let isStriking = false;
let strikeProgress = 0; // 0 to 1

function triggerForgeStrike() {
  audio.playStrike();
  state.forgeStrikes++;
  state.forgeHeat = Math.min(3200, state.forgeHeat + 350);

  // Show Toast
  const toast = document.getElementById('strike-toast');
  const toastText = document.getElementById('toast-text');
  if (toast && toastText) {
    const powerBonus = Math.floor(250 + Math.random() * 300);
    toastText.textContent = `⚡ FORGE IMPACT! +${powerBonus} MORU POWER (${state.forgeHeat} °C)`;
    toast.classList.add('show');
    clearTimeout(toast._timeout);
    toast._timeout = setTimeout(() => {
      toast.classList.remove('show');
    }, 1800);
  }

  // Trigger hammer slam animation
  isStriking = true;
  strikeProgress = 0;

  // Flash Point Lights
  forgeLight.intensity = 14.0;
  anvilRuneLight.intensity = 8.0;

  // Trigger Shockwave
  shockwaveActive = true;
  shockwaveScale = 1.0;
  shockwaveMat.opacity = 1.0;

  // Trigger Sparks Explosion
  sparkMat.opacity = 1.0;
  const posArr = sparkGeo.attributes.position.array;
  for (let i = 0; i < SPARK_COUNT; i++) {
    posArr[i * 3] = 0;
    posArr[i * 3 + 1] = 3.65;
    posArr[i * 3 + 2] = 0;

    const angle = Math.random() * Math.PI * 2;
    const speed = 7.0 + Math.random() * 16.0;
    const upSpeed = 6.0 + Math.random() * 14.0;
    sparkVelocities[i].set(
      Math.cos(angle) * speed,
      upSpeed,
      Math.sin(angle) * speed
    );
    sparkLifetimes[i] = 1.0;
  }
  sparkGeo.attributes.position.needsUpdate = true;

  // Screen shake
  cameraShakeTime = 0.35;
  cameraShakeIntensity = 1.4;

  // Cats surprise jump
  state.cats.forEach(cat => cat.triggerSurprise());
}
state.strikeForge = triggerForgeStrike;

// --- Cute 3D Moru Cat Model Builder & Class ---
const catBreeds = [
  { name: 'Kuro', coat: 0x141824, belly: 0x222a38, ear: 0xff66aa, eye: 0x00ffaa, collar: 0x00f0ff },
  { name: 'Mikan', coat: 0xe67300, belly: 0xffe0b2, ear: 0xff88aa, eye: 0x225500, collar: 0xffaa00 },
  { name: 'Yuki', coat: 0xf5f8ff, belly: 0xffffff, ear: 0xff88aa, eye: 0x0088ff, collar: 0xff2a85 },
  { name: 'Calico', coat: 0xd97724, belly: 0xffffff, ear: 0xff99bb, eye: 0xd4a017, collar: 0x00ff88 },
  { name: 'Titan', coat: 0x3d485e, belly: 0x627394, ear: 0xff4500, eye: 0xffaa00, collar: 0xff5500 },
  { name: 'Sakura', coat: 0xffc4db, belly: 0xffffff, ear: 0xff4f9a, eye: 0x9b59b6, collar: 0x00f0ff }
];

class MoruCat {
  constructor(index, breedIndex = null, startPos = null) {
    this.index = index;
    const breed = breedIndex !== null
      ? catBreeds[breedIndex % catBreeds.length]
      : catBreeds[Math.floor(Math.random() * catBreeds.length)];
    this.breed = breed;
    this.name = breed.name;

    this.group = new THREE.Group();
    this.group.name = `moru-cat-${index}`;

    // Locomotion state
    this.pos = new THREE.Vector3(0, 0, 0);
    this.target = new THREE.Vector3(0, 0, 0);
    this.heading = 0;
    this.speed = 3.2 + Math.random() * 2.2;
    this.animTime = Math.random() * 10;
    this.isJumping = false;
    this.jumpProgress = 0;
    this.jumpHeight = 1.6;
    this.isSurprised = false;
    this.surpriseTimer = 0;

    // Build the cat mesh hierarchy
    this.buildMesh();

    // Spawn location & initial target
    if (startPos) {
      this.pos.copy(startPos);
    } else {
      const startAngle = (index / 6) * Math.PI * 2;
      const startDist = 10 + Math.random() * 14;
      this.pos.set(Math.cos(startAngle) * startDist, 0, Math.sin(startAngle) * startDist);
    }
    this.group.position.copy(this.pos);
    this.pickNewTarget();

    scene.add(this.group);
  }

  buildMesh() {
    const coatMat = new THREE.MeshStandardMaterial({
      color: this.breed.coat,
      roughness: 0.65,
      metalness: 0.1
    });

    const bellyMat = new THREE.MeshStandardMaterial({
      color: this.breed.belly,
      roughness: 0.7,
      metalness: 0.05
    });

    const innerEarMat = new THREE.MeshBasicMaterial({ color: this.breed.ear });
    const eyeMat = new THREE.MeshBasicMaterial({ color: this.breed.eye });
    const pupilMat = new THREE.MeshBasicMaterial({ color: 0x080808 });
    const noseMat = new THREE.MeshBasicMaterial({ color: 0xff6b8b });
    const collarMat = new THREE.MeshBasicMaterial({ color: this.breed.collar });
    const goldMat = new THREE.MeshStandardMaterial({ color: 0xffcc00, metalness: 0.85, roughness: 0.2 });

    // Root Body Group (handles walk bobbing)
    this.bodyGroup = new THREE.Group();
    this.bodyGroup.position.y = 0.75;
    this.group.add(this.bodyGroup);

    // Chubby Torso (Capsule/Cylinder)
    const torsoGeo = new THREE.CapsuleGeometry(0.48, 0.65, 8, 16);
