    const eyeGeo = new THREE.SphereGeometry(0.14, 12, 12);
    const pupilGeo = new THREE.SphereGeometry(0.09, 12, 12);
    const catchGeo = new THREE.SphereGeometry(0.04, 8, 8);
    const catchMat = new THREE.MeshBasicMaterial({ color: 0xffffff });

    // Eye Left
    const eyeL = new THREE.Mesh(eyeGeo, eyeMat);
    eyeL.position.set(-0.24, 0.1, -0.38);
    eyeL.scale.set(1.0, 1.25, 0.5);
    this.headGroup.add(eyeL);

    const pupilL = new THREE.Mesh(pupilGeo, pupilMat);
    pupilL.position.set(-0.24, 0.1, -0.44);
    pupilL.scale.set(0.6, 1.1, 0.3);
    this.headGroup.add(pupilL);

    const catchL = new THREE.Mesh(catchGeo, catchMat);
    catchL.position.set(-0.21, 0.15, -0.47);
    this.headGroup.add(catchL);

    // Eye Right
    const eyeR = new THREE.Mesh(eyeGeo, eyeMat);
    eyeR.position.set(0.24, 0.1, -0.38);
    eyeR.scale.set(1.0, 1.25, 0.5);
    this.headGroup.add(eyeR);

    const pupilR = new THREE.Mesh(pupilGeo, pupilMat);
    pupilR.position.set(0.24, 0.1, -0.44);
    pupilR.scale.set(0.6, 1.1, 0.3);
    this.headGroup.add(pupilR);

    const catchR = new THREE.Mesh(catchGeo, catchMat);
    catchR.position.set(0.27, 0.15, -0.47);
    this.headGroup.add(catchR);

    // 4 Articulated Legs
    const legGeo = new THREE.CylinderGeometry(0.12, 0.11, 0.55, 10);
    const pawGeo = new THREE.SphereGeometry(0.13, 8, 8);

    const createLeg = (x, z) => {
      const legGroup = new THREE.Group();
      legGroup.position.set(x, 0, z);

      const leg = new THREE.Mesh(legGeo, coatMat);
      leg.position.y = -0.28;
      leg.castShadow = true;
      legGroup.add(leg);

      const paw = new THREE.Mesh(pawGeo, bellyMat);
      paw.position.set(0, -0.52, -0.04);
      paw.scale.set(1.1, 0.8, 1.3);
      legGroup.add(paw);

      this.bodyGroup.add(legGroup);
      return legGroup;
    };

    this.legFL = createLeg(-0.3, -0.32);
    this.legFR = createLeg(0.3, -0.32);
    this.legBL = createLeg(-0.3, 0.32);
    this.legBR = createLeg(0.3, 0.32);

    // Multi-segmented Sinuous Tail
    this.tailGroup = new THREE.Group();
    this.tailGroup.position.set(0, 0.2, 0.45);
    this.bodyGroup.add(this.tailGroup);

    this.tailSegments = [];
    let currentParent = this.tailGroup;
    for (let i = 0; i < 4; i++) {
      const segGeo = new THREE.CylinderGeometry(0.09 - i * 0.015, 0.11 - i * 0.015, 0.28, 8);
      const segMesh = new THREE.Mesh(segGeo, coatMat);
      segMesh.position.y = 0.14;
      segMesh.rotation.x = 0.4;

      const segNode = new THREE.Group();
      if (i > 0) segNode.position.y = 0.24;
      segNode.add(segMesh);
      currentParent.add(segNode);
      this.tailSegments.push(segNode);
      currentParent = segNode;
    }

    // Selection Halo Ring (hidden by default)
    const haloGeo = new THREE.RingGeometry(0.65, 0.75, 32);
    const haloMat = new THREE.MeshBasicMaterial({
      color: this.breed.collar,
      side: THREE.DoubleSide,
      transparent: true,
      opacity: 0.9
    });
    this.halo = new THREE.Mesh(haloGeo, haloMat);
    this.halo.rotation.x = -Math.PI / 2;
    this.halo.position.y = 0.06;
    this.halo.visible = false;
    this.group.add(this.halo);
  }

  pickNewTarget() {
    // Generate intelligent waypoints: Plaza circle, spokes, and streets
    const pickMode = Math.random();
    if (pickMode < 0.45) {
      // Plaza circle patrol
      const rad = 6.0 + Math.random() * 14.0;
      const angle = Math.random() * Math.PI * 2;
      this.target.set(Math.cos(angle) * rad, 0, Math.sin(angle) * rad);
    } else if (pickMode < 0.75) {
      // Ring Road sidewalk
      const rad = 24.5 + Math.random() * 7.5;
      const angle = Math.random() * Math.PI * 2;
      this.target.set(Math.cos(angle) * rad, 0, Math.sin(angle) * rad);
    } else {
      // Boulevard avenue promenade
      const dir = Math.floor(Math.random() * 4);
      const dist = 32 + Math.random() * 35;
      const spread = (Math.random() - 0.5) * 6;
      if (dir === 0) this.target.set(spread, 0, dist);
      else if (dir === 1) this.target.set(spread, 0, -dist);
      else if (dir === 2) this.target.set(dist, 0, spread);
      else this.target.set(-dist, 0, spread);
    }

    // Chance to perform a jump during route
    if (Math.random() < 0.35) {
      this.isJumping = true;
      this.jumpProgress = 0;
      this.jumpHeight = 1.0 + Math.random() * 1.4;
    }
  }

  triggerSurprise() {
    this.isSurprised = true;
    this.surpriseTimer = 0.8;
    this.isJumping = true;
    this.jumpProgress = 0;
    this.jumpHeight = 2.4; // High excited bounce!
  }

  pet() {
    audio.playMeow();
    this.triggerSurprise();
    createHeartBurst(this.pos.clone().add(new THREE.Vector3(0, 1.8, 0)));
  }

  update(dt) {
    this.animTime += dt * (this.speed * 1.8);

    // Vector to target
    const toTarget = new THREE.Vector3().subVectors(this.target, this.pos);
    toTarget.y = 0;
    const dist = toTarget.length();

    if (dist < 1.4) {
      this.pickNewTarget();
    } else {
      toTarget.normalize();
      // Move forward
      this.pos.addScaledVector(toTarget, this.speed * dt);
      this.group.position.x = this.pos.x;
      this.group.position.z = this.pos.z;

      // Smooth heading rotation
      const targetAngle = Math.atan2(toTarget.x, toTarget.z) + Math.PI;
      let diff = targetAngle - this.heading;
      while (diff < -Math.PI) diff += Math.PI * 2;
      while (diff > Math.PI) diff -= Math.PI * 2;
      this.heading += diff * Math.min(1.0, dt * 6.0);
      this.group.rotation.y = this.heading;
    }

    // Elevation handling (Ground vs Central Plaza Dais)
    const distFromCenter = Math.hypot(this.pos.x, this.pos.z);
    let floorY = 0;
    if (distFromCenter < 5.4) {
      floorY = 0.95; // on top dais
    } else if (distFromCenter < 6.4) {
      floorY = 0.55; // on lower dais
    } else if (distFromCenter < 23.0) {
      floorY = 0.35; // on plaza
    }

    // Jump Physics
    if (this.isJumping) {
      this.jumpProgress += dt * 2.2;
      if (this.jumpProgress >= 1.0) {
        this.isJumping = false;
        this.jumpProgress = 0;
      }
    }

    const jumpOffset = this.isJumping ? Math.sin(this.jumpProgress * Math.PI) * this.jumpHeight : 0;
    this.group.position.y = floorY + jumpOffset;

    // Body Bobbing & Trot Leg Swing Animation
    const stride = Math.sin(this.animTime * 3.5);
    const altStride = Math.cos(this.animTime * 3.5);

    if (this.isJumping) {
      // Paws tucked/extended in jump pose
      this.legFL.rotation.x = -0.55;
      this.legFR.rotation.x = -0.55;
      this.legBL.rotation.x = 0.65;
      this.legBR.rotation.x = 0.65;
      this.bodyGroup.position.y = 0.75 + Math.sin(this.jumpProgress * Math.PI) * 0.2;
    } else {
      // Trot gait (diagonal leg pairs)
      this.legFL.rotation.x = stride * 0.65;
      this.legBR.rotation.x = stride * 0.65;
      this.legFR.rotation.x = -stride * 0.65;
      this.legBL.rotation.x = -stride * 0.65;

      this.bodyGroup.position.y = 0.75 + Math.abs(stride) * 0.08;
    }

    // Head tilt
    this.headGroup.rotation.z = Math.sin(this.animTime * 1.5) * 0.08;
    this.headGroup.rotation.x = Math.cos(this.animTime * 1.8) * 0.06;

    // Sinuous Tail Wave
    this.tailSegments.forEach((seg, i) => {
      seg.rotation.z = Math.sin(this.animTime * 2.2 + i * 0.6) * 0.18;
      seg.rotation.x = 0.35 + Math.cos(this.animTime * 1.8 + i * 0.4) * 0.12;
    });

    // Surprise recovery
    if (this.isSurprised) {
      this.surpriseTimer -= dt;
      if (this.surpriseTimer <= 0) {
        this.isSurprised = false;
      }
    }

    // Halo pulse animation if selected
    if (this.halo.visible) {
      const pulse = 1.0 + Math.sin(this.animTime * 5.0) * 0.12;
      this.halo.scale.set(pulse, pulse, pulse);
    }
  }
}

