  drone.userData = {
    radius: 36 + i * 8,
    height: 18 + i * 3.5,
    speed: 0.4 + i * 0.12,
    angle: (i / 6) * Math.PI * 2
  };
  cityGroup.add(drone);
  drones.push(drone);
}

// --- Camera Modes & Smooth Transition Controller ---
const cameraTargets = {
  overview: {
    pos: new THREE.Vector3(0, 85, 115),
    target: new THREE.Vector3(0, 4, 0)
  },
  iso: {
    pos: new THREE.Vector3(65, 55, 65),
    target: new THREE.Vector3(0, 3, 0)
  },
  street: {
    pos: new THREE.Vector3(0, 3.8, 32),
    target: new THREE.Vector3(0, 6.5, 0)
  },
  'follow-cat': {
    pos: new THREE.Vector3(0, 8, 12),
    target: new THREE.Vector3(0, 1, 0)
  }
};

let currentCamMode = 'overview';
let isTransitioningCam = false;
let camLerpProgress = 1.0;
const camStartPos = new THREE.Vector3();
const camEndPos = new THREE.Vector3();
const camStartTarget = new THREE.Vector3();
const camEndTarget = new THREE.Vector3();

function setCameraMode(mode) {
  state.cameraMode = mode;
  currentCamMode = mode;

  document.querySelectorAll('.btn-toggle[id^="cam-"]').forEach(btn => btn.classList.remove('active'));
  const activeBtn = document.getElementById(`cam-${mode}`);
  if (activeBtn) activeBtn.classList.add('active');

  const hudCam = document.getElementById('hud-cam');
  if (hudCam) {
    const titles = { overview: 'Overview', iso: 'Isometric', street: 'Street Level', 'follow-cat': 'Follow Cat' };
    hudCam.textContent = titles[mode] || mode;
  }

  if (mode !== 'follow-cat') {
    const cfg = cameraTargets[mode];
    if (cfg) {
      camStartPos.copy(camera.position);
      camEndPos.copy(cfg.pos);
      camStartTarget.copy(controls.target);
      camEndTarget.copy(cfg.target);
      camLerpProgress = 0;
      isTransitioningCam = true;
    }
  }
}
state.setCameraMode = setCameraMode;

// Pause / Resume Motion Toggle
function togglePause() {
  state.isPaused = !state.isPaused;
  const toggleBtn = document.getElementById('toggle-spin');
  const spinIcon = document.getElementById('spin-icon');
  const spinText = document.getElementById('spin-text');
  const hudState = document.getElementById('hud-state');

  if (toggleBtn) {
    if (state.isPaused) {
      toggleBtn.classList.add('paused');
      if (spinIcon) spinIcon.textContent = '▶️';
      if (spinText) spinText.textContent = 'Resume Motion';
      if (hudState) {
        hudState.textContent = 'Paused';
        hudState.style.color = '#ff80bf';
      }
    } else {
      toggleBtn.classList.remove('paused');
      if (spinIcon) spinIcon.textContent = '⏸️';
      if (spinText) spinText.textContent = 'Pause Motion';
      if (hudState) {
        hudState.textContent = 'Running';
        hudState.style.color = '#00ff88';
      }
    }
  }
}
state.togglePause = togglePause;

// --- Raycaster for Interactive Cat Petting & Selection ---
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

window.addEventListener('pointerdown', (e) => {
  // Only trigger on canvas clicks, not on UI overlays
  if (e.target !== canvas) return;

  mouse.x = (e.clientX / window.innerWidth) * 2 - 1;
  mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);

  // Check intersection with cats
  for (let i = 0; i < state.cats.length; i++) {
    const cat = state.cats[i];
    const intersects = raycaster.intersectObjects(cat.group.children, true);
    if (intersects.length > 0) {
      selectCat(i);
      return;
    }
  }

  // Check intersection with Anvil
  const anvilHits = raycaster.intersectObjects(anvilGroup.children, true);
  if (anvilHits.length > 0) {
    triggerForgeStrike();
  }
});

// --- Keyboard Hotkeys ---
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    e.preventDefault();
    triggerForgeStrike();
  } else if (e.key === 'c' || e.key === 'C') {
    spawnNewCat();
  } else if (e.key === 'p' || e.key === 'P') {
    togglePause();
  } else if (e.key === '1') {
    setCameraMode('overview');
  } else if (e.key === '2') {
    setCameraMode('iso');
  } else if (e.key === '3') {
    setCameraMode('street');
  } else if (e.key === '4') {
    setCameraMode('follow-cat');
  }
});

// --- UI Button Event Bindings ---
const btnForge = document.getElementById('btn-forge-strike');
if (btnForge) btnForge.addEventListener('click', () => triggerForgeStrike());

const btnSpawn = document.getElementById('btn-spawn-cat');
if (btnSpawn) btnSpawn.addEventListener('click', () => spawnNewCat());

const btnToggleSpin = document.getElementById('toggle-spin');
if (btnToggleSpin) btnToggleSpin.addEventListener('click', () => togglePause());

const camButtons = [
  { id: 'cam-overview', mode: 'overview' },
  { id: 'cam-iso', mode: 'iso' },
  { id: 'cam-street', mode: 'street' },
  { id: 'cam-follow-cat', mode: 'follow-cat' }
];
camButtons.forEach(({ id, mode }) => {
  const btn = document.getElementById(id);
  if (btn) btn.addEventListener('click', () => setCameraMode(mode));
});

const themeButtons = [
  { id: 'mode-night', theme: 'night' },
  { id: 'mode-gold', theme: 'gold' },
  { id: 'mode-day', theme: 'day' }
];
themeButtons.forEach(({ id, theme }) => {
  const btn = document.getElementById(id);
  if (btn) btn.addEventListener('click', () => applyTheme(theme));
});

// --- Window Resize Listener ---
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// --- Main Animation Loop & Frame Telemetry ---
let lastTime = performance.now();
let frameCount = 0;
let lastFpsUpdateTime = performance.now();
const hudFps = document.getElementById('hud-fps');
const hudCats = document.getElementById('hud-cats');
const hudHeat = document.getElementById('hud-heat');
const hudStrikes = document.getElementById('hud-strikes');

function animate() {
  requestAnimationFrame(animate);

  const now = performance.now();
  let dt = (now - lastTime) / 1000;
  lastTime = now;
  if (dt > 0.1) dt = 0.1; // clamp delta time

  // FPS calculation
  frameCount++;
  if (now - lastFpsUpdateTime >= 400) {
    state.fps = Math.round((frameCount * 1000) / (now - lastFpsUpdateTime));
    frameCount = 0;
    lastFpsUpdateTime = now;

    if (hudFps) hudFps.textContent = `${state.fps} FPS`;
    if (hudCats) hudCats.textContent = `${state.cats.length} Cats`;
    if (hudHeat) hudHeat.textContent = `${Math.round(state.forgeHeat).toLocaleString()} °C`;
    if (hudStrikes) hudStrikes.textContent = `${state.forgeStrikes} Hits`;
  }

  // Simulation updates (only when not paused)
  if (!state.isPaused) {
    // 1. Cool down forge anvil heat slowly
    if (state.forgeHeat > 1200) {
      state.forgeHeat = Math.max(1200, state.forgeHeat - dt * 65);
    }

    // 2. Animate Holographic Forge Rings
    holoRing1.rotation.z += dt * 0.8;
    holoRing2.rotation.x += dt * 0.6;

    // 3. Hammer Animation
    if (isStriking) {
      strikeProgress += dt * 3.8;
      if (strikeProgress < 0.25) {
        // High recoil up
        hammerArmGroup.rotation.z = 0.55 + strikeProgress * 3.5;
      } else if (strikeProgress < 0.5) {
        // High speed slam down to 0 (impact)
        const p = (strikeProgress - 0.25) / 0.25;
        hammerArmGroup.rotation.z = (1 - p) * 1.4;
      } else if (strikeProgress < 1.0) {
        // Settle & bounce back
        const p = (strikeProgress - 0.5) / 0.5;
        hammerArmGroup.rotation.z = Math.sin(p * Math.PI) * 0.25 + (1 - p) * 0.1 + p * 0.55;
      } else {
        isStriking = false;
        hammerArmGroup.rotation.z = 0.55;
      }
    } else {
      // Gentle floating idle breathing
      hammerArmGroup.rotation.z = 0.55 + Math.sin(now * 0.002) * 0.06;
    }

    // 4. Update Cats
    state.cats.forEach(cat => cat.update(dt));

    // 5. Update Flying Sky Drones
    drones.forEach(d => {
      d.userData.angle += d.userData.speed * dt * 0.4;
      const dx = Math.cos(d.userData.angle) * d.userData.radius;
      const dz = Math.sin(d.userData.angle) * d.userData.radius;
      d.position.set(dx, d.userData.height, dz);
      d.rotation.y = -d.userData.angle - Math.PI / 2;
    });

    // 6. Update Sparks Particle System
    if (sparkMat.opacity > 0.01) {
      const posArr = sparkGeo.attributes.position.array;
      let anyAlive = false;
      for (let i = 0; i < SPARK_COUNT; i++) {
        if (sparkLifetimes[i] > 0) {
          anyAlive = true;
          sparkLifetimes[i] -= dt * 1.6;
          sparkVelocities[i].y -= 24.0 * dt; // Gravity

          posArr[i * 3] += sparkVelocities[i].x * dt;
          posArr[i * 3 + 1] += sparkVelocities[i].y * dt;
          posArr[i * 3 + 2] += sparkVelocities[i].z * dt;

          // Bounce on floor dais
          if (posArr[i * 3 + 1] < 1.15) {
            posArr[i * 3 + 1] = 1.15;
            sparkVelocities[i].y *= -0.45;
            sparkVelocities[i].x *= 0.7;
            sparkVelocities[i].z *= 0.7;
          }
        }
      }
      sparkGeo.attributes.position.needsUpdate = true;
      if (!anyAlive) {
        sparkMat.opacity = Math.max(0, sparkMat.opacity - dt * 2.0);
      }
    }

    // 7. Update Shockwave
    if (shockwaveActive) {
      shockwaveScale += dt * 16.0;
      shockwave.scale.set(shockwaveScale, shockwaveScale, 1);
      shockwaveMat.opacity -= dt * 2.2;
      if (shockwaveMat.opacity <= 0) {
        shockwaveActive = false;
        shockwaveMat.opacity = 0;
      }
    }

    // 8. Forge Point Lights Decay back to normal
    if (forgeLight.intensity > 4.2) {
      forgeLight.intensity = Math.max(4.2, forgeLight.intensity - dt * 18.0);
    }
    if (anvilRuneLight.intensity > 2.5) {
      anvilRuneLight.intensity = Math.max(2.5, anvilRuneLight.intensity - dt * 10.0);
    }

    // 9. Floating Heart Particles
    for (let i = hearts.length - 1; i >= 0; i--) {
      const h = hearts[i];
      h.userData.life -= dt * 1.4;
      h.position.addScaledVector(h.userData.vel, dt);
      h.scale.multiplyScalar(0.98);
      h.material.opacity = Math.max(0, h.userData.life);
      if (h.userData.life <= 0) {
        scene.remove(h);
        hearts.splice(i, 1);
      }
    }
  }

  // Camera Management & Follow Mode
  if (currentCamMode === 'follow-cat') {
    const activeCat = state.cats[state.activeCatIndex] || state.cats[0];
    if (activeCat) {
      // 3rd-person chase camera calculation
      const catPos = activeCat.pos;
      const heading = activeCat.heading;
      const offsetDist = 6.5;
      const offsetHeight = 3.2;

      const targetCamPos = new THREE.Vector3(
        catPos.x - Math.sin(heading) * offsetDist,
        catPos.y + offsetHeight,
        catPos.z - Math.cos(heading) * offsetDist
      );

      const lookTarget = new THREE.Vector3(
        catPos.x,
        catPos.y + 1.2,
        catPos.z
      );

      // Smooth damping follow
      camera.position.lerp(targetCamPos, dt * 5.5);
      controls.target.lerp(lookTarget, dt * 6.5);
    }
  } else if (isTransitioningCam) {
    camLerpProgress += dt * 2.2;
    // Cubic ease out
    const t = Math.min(1.0, camLerpProgress);
    const ease = 1 - Math.pow(1 - t, 3);

    camera.position.lerpVectors(camStartPos, camEndPos, ease);
    controls.target.lerpVectors(camStartTarget, camEndTarget, ease);

    if (t >= 1.0) {
      isTransitioningCam = false;
    }
  }

  // Camera Screen Shake from Anvil Strikes
  if (cameraShakeTime > 0) {
    cameraShakeTime -= dt;
    const shakeX = (Math.random() - 0.5) * cameraShakeIntensity;
    const shakeY = (Math.random() - 0.5) * cameraShakeIntensity;
    const shakeZ = (Math.random() - 0.5) * cameraShakeIntensity;
    camera.position.add(new THREE.Vector3(shakeX, shakeY, shakeZ));
    cameraShakeIntensity = Math.max(0, cameraShakeIntensity - dt * 3.5);
  }

  controls.update();
  renderer.render(scene, camera);
}

// Start Animation Loop
animate();




