  const groundPoint = new THREE.Vector3();
  const down = new THREE.Vector3(0, -1, 0);
  function syncShadow() {
    catRoot.updateWorldMatrix(true, false);
    catRoot.getWorldPosition(groundPoint);
    groundRay.set(groundPoint.setY(3), down);
    const hit = groundRay.intersectObjects(groundReceivers, false)[0];
    groundPoint.y = (hit ? hit.point.y : -0.05) + 0.01;
    shadowDisc.position.copy(catRoot.worldToLocal(groundPoint));
  }
  syncShadow();

  // Locomotion update function
  function update(delta, time) {
    // 1. Move cat in world coordinates
    const walkSpeed = 3.6;
    let forwardAngle = 0;

    if (pathType === 2) {
      // Trot along avenue
      avenueProgress += avenueDirection * delta * (0.08 * walkSpeed);
      if (avenueProgress > 1.0) {
        avenueProgress = 1.0;
        avenueDirection = -1;
      } else if (avenueProgress < 0.0) {
        avenueProgress = 0.0;
        avenueDirection = 1;
