    sunIntensity: 1.30,
    ambientColor: 0x607d8b,
    ambientIntensity: 0.80,
    hemiSky: 0x82b1ff,
    hemiGround: 0x455a64,
    hemiIntensity: 0.7,
    exposure: 0.95,
    bloomStrength: 0.35,
    bloomThreshold: 0.85,
    bloomRadius: 0.30
  }
};

function applyTheme(themeName) {
  const t = THEMES[themeName] || THEMES.night;
  state.theme = themeName;
  state.disposedCount = (state.disposedCount || 0) + 1;

  // Update URL search param cleanly without full page refresh
  const url = new URL(window.location.href);
  url.searchParams.set('theme', themeName);
  window.history.replaceState(null, '', url.toString());

  // Apply visual theme parameters
  scene.background = new THREE.Color(t.bg);
  scene.fog = new THREE.Fog(t.fogColor, t.fogNear, t.fogFar);

  sunLight.color.setHex(t.sunColor);
  sunLight.intensity = t.sunIntensity;
  const sunPositions = {
    night: [60, 90, 50],
    gold: [-90, 40, 40],
    day: [60, 90, 50]
  };
  sunLight.position.set(...(sunPositions[themeName] || sunPositions.night));

  ambientLight.color.setHex(t.ambientColor);
  ambientLight.intensity = t.ambientIntensity;

  hemiLight.color.setHex(t.hemiSky);
  hemiLight.groundColor.setHex(t.hemiGround);
  hemiLight.intensity = t.hemiIntensity;

  renderer.toneMappingExposure = t.exposure;
  bloomPass.strength = t.bloomStrength;
  bloomPass.threshold = t.bloomThreshold;
  bloomPass.radius = t.bloomRadius;

  // Update UI button highlights
  ['night', 'gold', 'day'].forEach(m => {
    const btn = document.getElementById(`mode-${m}`);
    if (btn) {
      if (m === themeName) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    }
  });

  if (!state.spinning) {
