    treeGroup.add(c2);

    const c3 = new THREE.Mesh(canopyTierGeo3, foliageMat);
    c3.position.y = 5.0;
    treeGroup.add(c3);

    // Position trees:
    // Distribution: 36 trees surrounding the plaza perimeter (radius 26 to 34),
    // and 48 trees lining the 4 avenues (radius 36 to 120).
    let tx, tz;
    if (i < 36) {
      // Plaza circle promenade
