import * as THREE from 'three';

/**
 * Procedural CanvasTexture generators for Moru 3D Neon Forge City.
 */

// Helper to create an offscreen canvas
function makeCanvas(width, height) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

/**
 * Procedural Skyscraper Window Facade Texture.
 * Generates rich, multi-colored illuminated window grids with floor bands and architectural details.
 */
export function createSkyscraperTexture(variant = 0) {
  const w = 512;
  const h = 1024;
  const canvas = makeCanvas(w, h);
  const ctx = canvas.getContext('2d');

  // Base building facade material color (deep metallic navy / gunmetal)
  const baseColors = ['#141724', '#161928', '#1a1f33'];
  ctx.fillStyle = baseColors[variant % baseColors.length];
  ctx.fillRect(0, 0, w, h);

  // Vertical architectural mullions / columns
  const cols = 16;
  const rows = 32;
  const padX = 6;
  const padY = 8;
  const cellW = (w - padX * (cols + 1)) / cols;
  const cellH = (h - padY * (rows + 1)) / rows;

  // Color palettes for illuminated windows depending on variant
  const palettes = [
    // Variant 0: Cyberpunk Neon (Cyan, Warm Amber, Neon Violet, Emerald)
    ['#38e8ff', '#ffd166', '#ff4d8d', '#06d6a0', '#74b9ff', '#f368e0'],
    // Variant 1: Golden Forge Corporate (Warm Amber, Golden Glow, Champagne, Cyan accents)
    ['#ffeaa7', '#fdcb6e', '#fab1a0', '#00cec9', '#ffeaa7', '#e17055'],
    // Variant 2: Midnight High-Tech Matrix (Electric Cyan, Ice Blue, Bright White, Mint)
    ['#00f2fe', '#4facfe', '#43e97b', '#38f9d7', '#ffffff', '#a8ff78']
  ];
  const palette = palettes[variant % palettes.length];

  // Draw structural vertical mullion lines
  ctx.fillStyle = '#0f111c';
  for (let c = 0; c <= cols; c++) {
    const x = c * (cellW + padX) + padX * 0.5;
    ctx.fillRect(x - 2, 0, 4, h);
  }

  // Draw floor plates (horizontal spandrels)
  for (let r = 0; r <= rows; r++) {
    const y = r * (cellH + padY) + padY * 0.5;
    ctx.fillStyle = (r % 4 === 0) ? '#282d46' : '#10121d';
    ctx.fillRect(0, y - 3, w, 6);

    // Occasional horizontal LED accent strip across facade
    if (r % 8 === 0) {
      ctx.fillStyle = palette[r % palette.length];
      ctx.globalAlpha = 0.85;
      ctx.fillRect(0, y - 1, w, 2);
      ctx.globalAlpha = 1.0;
    }
  }

  // Draw windows
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = padX + c * (cellW + padX);
      const y = padY + r * (cellH + padY);

      // Deterministic pseudo-randomness for window lights
      const seed = Math.sin(r * 127.1 + c * 311.7 + variant * 47.9) * 43758.5453;
      const rand = seed - Math.floor(seed);

      // ~65% of windows are illuminated in varying intensities
      if (rand > 0.35) {
        const color = palette[Math.floor(rand * palette.length)];
        ctx.fillStyle = color;
        // Varying window brightness for rich depth
        ctx.globalAlpha = 0.55 + (rand * 0.45);
        ctx.fillRect(x, y, cellW, cellH);

        // Soft window frame / inner reflection
        ctx.strokeStyle = '#ffffff';
        ctx.globalAlpha = 0.3;
        ctx.lineWidth = 1;
        ctx.strokeRect(x + 1, y + 1, cellW - 2, cellH - 2);
      } else {
        // Dark unlit window with subtle dark blue sheen
        ctx.fillStyle = '#080a12';
        ctx.globalAlpha = 0.95;
        ctx.fillRect(x, y, cellW, cellH);
      }
    }
  }
  ctx.globalAlpha = 1.0;

  // Add subtle vertical LED light conduit up one side
  if (variant === 0 || variant === 2) {
    ctx.fillStyle = '#00f2fe';
    ctx.globalAlpha = 0.8;
    ctx.fillRect(w - 6, 0, 4, h);
    ctx.globalAlpha = 1.0;
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

/**
 * Paved Road Texture with crisp lane markings, dashed center line, and crosswalk.
 */
export function createRoadTexture() {
  const w = 512;
  const h = 512;
  const canvas = makeCanvas(w, h);
  const ctx = canvas.getContext('2d');

  // Dark asphalt base with subtle texture
  ctx.fillStyle = '#1c1f2b';
  ctx.fillRect(0, 0, w, h);

  // Subtle asphalt grain noise
  ctx.fillStyle = '#242838';
  for (let i = 0; i < 4000; i++) {
    const rx = Math.random() * w;
    const ry = Math.random() * h;
    ctx.fillRect(rx, ry, 2, 2);
  }

  // Outer curb boundary lines (solid cyan-white)
  ctx.fillStyle = '#d4e6f1';
  ctx.fillRect(24, 0, 6, h);
  ctx.fillRect(w - 30, 0, 6, h);

  // Dashed glowing center dividing line (neon yellow / amber)
  ctx.fillStyle = '#ffd166';
  const dashH = 32;
  const gapH = 20;
  const dashCount = Math.ceil(h / (dashH + gapH));
  for (let i = 0; i < dashCount; i++) {
    const y = i * (dashH + gapH);
    ctx.fillRect(w / 2 - 3, y, 6, dashH);
  }

  // Crosswalk zebra stripes at bottom segment
  ctx.fillStyle = '#f8f9fa';
  const zebraY = h - 90;
  const barH = 50;
  const barW = 24;
  const barGap = 16;
  const barTotal = barW + barGap;
  const startX = 40;
  const endX = w - 40;
  for (let x = startX; x + barW <= endX; x += barTotal) {
    ctx.fillRect(x, zebraY, barW, barH);
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

/**
 * Glowing Ancient Blacksmith Rune Ring Texture.
 * Concentric sacred geometry, rune inscriptions, and central anvil crest.
 */
export function createRuneTexture() {
  const size = 1024;
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');
  const cx = size / 2;
  const cy = size / 2;

  ctx.clearRect(0, 0, size, size);

  // Concentric decorative glowing rune circles
  const rings = [480, 440, 390, 320, 240, 160];
  ctx.strokeStyle = '#00f2fe';
  ctx.shadowColor = '#00d2ff';
  ctx.shadowBlur = 12;

  rings.forEach((r, idx) => {
    ctx.lineWidth = (idx % 2 === 0) ? 4 : 2;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
  });

  // Intersecting 8-pointed sacred star (octagram)
  ctx.strokeStyle = '#ffd166';
  ctx.shadowColor = '#ffaa00';
  ctx.lineWidth = 3;
  ctx.beginPath();
  const starPoints = 8;
  const outerR = 440;
  const innerR = 320;
  for (let i = 0; i < starPoints * 2; i++) {
    const angle = (i * Math.PI) / starPoints;
    const radius = (i % 2 === 0) ? outerR : innerR;
    const px = cx + Math.cos(angle) * radius;
    const py = cy + Math.sin(angle) * radius;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();

  // Draw ancient geometric rune glyphs along the outer ring
  const glyphCount = 32;
  const glyphR = 415;
  ctx.fillStyle = '#ffffff';
  ctx.shadowColor = '#00f2fe';
  ctx.shadowBlur = 8;
  ctx.font = 'bold 22px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  const runes = ['ᚠ', 'ᚢ', 'ᚦ', 'ᚨ', 'ᚱ', 'ᚲ', 'ᚷ', 'ᚹ', 'ᚺ', 'ᚾ', 'ᛁ', 'ᛃ', 'ᛈ', 'ᛇ', 'ᛉ', 'ᛊ',
                 'ᛏ', 'ᛒ', 'ᛖ', 'ᛗ', 'ᛚ', 'ᛜ', 'ᛞ', 'ᛟ', '⚒', '⚔', '⚡', '✦', '✧', '★', '⚙', '◈'];

  for (let i = 0; i < glyphCount; i++) {
    const angle = (i * 2 * Math.PI) / glyphCount;
    const gx = cx + Math.cos(angle) * glyphR;
    const gy = cy + Math.sin(angle) * glyphR;
    ctx.save();
    ctx.translate(gx, gy);
    ctx.rotate(angle + Math.PI / 2);
    ctx.fillText(runes[i % runes.length], 0, 0);
    ctx.restore();
  }

  // Secondary inner rune ring
  const innerGlyphCount = 16;
  const innerGlyphR = 280;
  ctx.fillStyle = '#ffd166';
  ctx.shadowColor = '#ff9900';
  ctx.font = 'bold 18px monospace';
  for (let i = 0; i < innerGlyphCount; i++) {
    const angle = (i * 2 * Math.PI) / innerGlyphCount;
    const gx = cx + Math.cos(angle) * innerGlyphR;
    const gy = cy + Math.sin(angle) * innerGlyphR;
    ctx.save();
    ctx.translate(gx, gy);
    ctx.rotate(angle + Math.PI / 2);
    ctx.fillText(runes[(i + 7) % runes.length], 0, 0);
    ctx.restore();
  }

  // Central anvil & hammer silhouette crest
  ctx.save();
  ctx.translate(cx, cy);
  ctx.fillStyle = '#ff7b25';
  ctx.shadowColor = '#ff5500';
  ctx.shadowBlur = 18;
  ctx.beginPath();
  // Stylized Anvil crest
  ctx.moveTo(-50, -25);
  ctx.lineTo(50, -25);
  ctx.lineTo(70, -10);
  ctx.lineTo(40, -10);
  ctx.lineTo(25, 15);
  ctx.lineTo(45, 35);
  ctx.lineTo(-45, 35);
  ctx.lineTo(-25, 15);
  ctx.lineTo(-40, -10);
  ctx.lineTo(-65, -10);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

/**
 * Streetlamp Ground Light Pool Disc Texture (soft radial glow).
 */
export function createLightPoolTexture(colorHex = '#ffe082') {
  const size = 256;
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');
  const cx = size / 2;
  const cy = size / 2;

  const grad = ctx.createRadialGradient(cx, cy, 4, cx, cy, size / 2);
  grad.addColorStop(0, colorHex);
  grad.addColorStop(0.3, 'rgba(255, 215, 120, 0.45)');
  grad.addColorStop(0.65, 'rgba(255, 180, 80, 0.15)');
  grad.addColorStop(1, 'rgba(0, 0, 0, 0)');

  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

/**
 * Molten Magma Texture for the forge hearth.
 */
export function createMagmaTexture() {
  const size = 512;
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');

  // Intense volcanic lava background
  ctx.fillStyle = '#ff3300';
  ctx.fillRect(0, 0, size, size);

  // Layered glowing magma veins
  for (let i = 0; i < 40; i++) {
    const grad = ctx.createRadialGradient(
      Math.random() * size, Math.random() * size, 10,
      Math.random() * size, Math.random() * size, 120
    );
    grad.addColorStop(0, '#ffff66');
    grad.addColorStop(0.3, '#ff7700');
    grad.addColorStop(0.7, '#cc1100');
    grad.addColorStop(1, '#330500');

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(Math.random() * size, Math.random() * size, Math.random() * 80 + 40, 0, Math.PI * 2);
    ctx.fill();
  }

  // Floating dark volcanic crust cracks
  ctx.strokeStyle = '#220800';
  ctx.lineWidth = 14;
  for (let i = 0; i < 15; i++) {
    ctx.beginPath();
    ctx.moveTo(Math.random() * size, Math.random() * size);
    for (let j = 0; j < 4; j++) {
      ctx.lineTo(Math.random() * size, Math.random() * size);
    }
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

/**
 * Helipad Roof Texture with 'H' insignia and neon landing ring.
 */
export function createHelipadTexture() {
  const size = 512;
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');
  const cx = size / 2;
  const cy = size / 2;

  // Dark rooftop surface
  ctx.fillStyle = '#181b26';
  ctx.fillRect(0, 0, size, size);

  // Outer safety perimeter
  ctx.strokeStyle = '#ffd166';
  ctx.lineWidth = 8;
  ctx.strokeRect(20, 20, size - 40, size - 40);

  // Bold landing circle
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 12;
  ctx.beginPath();
  ctx.arc(cx, cy, 180, 0, Math.PI * 2);
  ctx.stroke();

  // Bold 'H' symbol
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 220px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('H', cx, cy + 8);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}




